import Foundation

private typealias E = EvidenceSeed

/// Alternate tellings, batch R: the same cases, played out another way.
extension StoryVariants {
    static let variantsR: [CaseTemplate] = [hotCarDeathV1, tellerDrawerV1, mailedPillsV1, fountainDestroyedV1, motherFalseAlibiV1, pickupLineSpeedingV1, movieSetGunV1, sergeantTicketCashV1, muralPaintOverV1, ambulanceEntryBlockV1, fourthDwiV1, taserMistakeV1, taxAgentGiftCardsV1, wetlandsFillDumpV1, courthouseHallFightV1, checkpointDwiV1, joggerChaseV1, loanForgivenessPhoneV1, dieselDrainageV1, lifeguardChairV1, streetRaceWreckV1, collegeHouseV1, deadWomanAccountsV1, parkingOfficeSafeV1, ticketTearScreamV1, texterCrashV1, truckStopKillerV1, electronicsCloneRingV1, elderHomeNightV1, neighborBoardPostV1, hitAndRunBumperV1, coldCaseGenealogyV1, barSkimmerPocketV1, restaurantFireClaimV1, mallBanReturnV1, dirtBikeStreetV1, coastalBodiesV1, willForgeryHeirV1]

    static let hotCarDeathV1 = SmallCases.make(
        key: "story.hotCarDeath",
        category: .violent,
        headlines: ["Toddler Found Dead in Minivan at Lake Marina Lot", "Boat Day Ends in Murder Charge for Parent"],
        law: "murder1",
        threshold: 6,
        spec: "With premeditation and deliberation, killed a 20-month-old child by leaving the child in a closed vehicle in extreme heat.",
        ages: 30...36,
        victim: false,
        summary: "On {DATE}, {D} strapped a 20-month-old into a minivan at a lake marina lot, cracked no windows, and spent five hours on a friend's boat in 95-degree heat. A dock worker saw the child through the glass at mid-afternoon and broke a window, but the child could not be revived. The day care had been closed that day. Investigators found a search on {DL}'s phone about how fast a closed car heats up, and angry messages to an ex about custody and money. {DL} says the plan was for a sitter to take the child, and that {D.he} believed the sitter had.",
        state: [E(.video, 3, "Marina Gate Camera", "{DL} locks the van and walks to the dock without opening the rear door."), E(.digital, 3, "Phone Searches", "A search two days earlier asks how fast a car heats up in summer."), E(.digital, 2, "Custody Messages", "Messages to an ex complain that raising the child is ruining {D.his} life."), E(.document, 2, "Boat Sign-Out", "{DL} signed the boat out at 9:10 a.m. for a five-hour trip.")],
        defense: [E(.document, 3, "Day Care Closure Notice", "An email sent the night before told parents the center was closed for the day."), E(.statement, 2, "Dock Worker Account", "The worker who found the child says {DL} collapsed and begged for help on return."), E(.document, 1, "Night Shift Schedule", "{DL} worked until 3 a.m. the night before.")],
        role: "Sheriff's detective",
        exam: [.direct("What did the marina gate camera show?", "\"It shows {D} locking the van and walking to the dock with a cooler at 9:05, without opening the rear door. No child is with {D.him}.\""), .direct("Where was the child?", "\"Strapped into a car seat in the closed van, with no windows cracked, in a marina lot with a 95-degree day.\""), .direct("Where did {D} spend those hours?", "\"On a friend's boat for about five hours. The boat sign-out shows {DL} signed it out at 9:10 a.m.\""), .direct("How was the child found?", "\"A dock worker saw the child through the glass at mid-afternoon and broke a window. The child could not be revived.\""), .direct("What was on the defendant's phone?", "\"A search two days earlier about how fast a closed car heats up, and messages to an ex complaining that raising the child was ruining {D.his} life.\""), .direct("What was the day care situation that morning?", "\"The day care was closed that day. Its closure email says so, though I cannot say whether {D.he} read it.\""), .cross("Can you say what the defendant believed about the child?", "\"No. I can only say where the child was and what the records show.\""), .cross("Did the search say anything about a child?", "\"No. It asked how fast a closed car heats up in summer. It did not mention a child or this day.\""), .cross("Did the defendant try to leave or hide?", "\"No. {D.He} was on the boat in plain sight and was told about the child on the dock.\""), .cross("How did the defendant react when told?", "\"With visible shock. {D.He} collapsed on the dock, and I saw that on the deputies' video.\""), .cross("Were the custody messages recent?", "\"Over several weeks. They show anger at an ex and strain, not a plan to harm the child.\"")],
        defenseRole: "Day care director",
        defenseExam: [.direct("What is your role?", "\"I direct a day care center. I handle enrollment, communication with parents, and closure notices.\""), .direct("When did the closure email go out?", "\"Close to 11 the night before. We had a staffing problem, and I sent it late.\""), .direct("Did parents open it?", "\"Many never did. Our open rate on late-night emails is low, and parents often miss them.\""), .direct("Did {D} confirm receiving it?", "\"No reply came. We do not require a reply, and many parents do not answer.\""), .direct("How did the defendant usually drop off?", "\"On time, every morning, with a backpack and a smile. {D} seemed devoted.\""), .direct("Was the defendant stressed?", "\"Often. {D.He} mentioned being short on sleep and juggling work and a custody schedule.\""), .cross("Did you call the defendant that morning?", "\"No. I did not call. I should have, and I live with that.\""), .cross("Did you know the child would be in the van?", "\"No. I did not know where the child was.\""), .cross("Did the email say the day care was closed all day?", "\"Yes. It said closed, and the date was in the subject line.\""), .cross("Did the defendant drop the child off on closed days before?", "\"No. This was the first time a closure caught {D.him}.\""), .cross("Do you blame {D}?", "\"I blame myself too. I do not know what {D.he} was thinking.\"")],
        theory: ("{D} left a child to die in a van and spent the day on a boat.", "A tired parent whose routine broke when the day care closed."),
        allocution: "\"I would give anything to take that morning back.\"",
        truths: ("A voice memo on {DL}'s phone the night before said, 'Nobody will blame me if it just happens.'", "A sitter's cancellation text sat unread in a phone left in the glove box, and {DL} asked the boat captain twice about the baby's bag."),
        defendant: [.direct("What happened that morning?", "\"I was running on no sleep. I thought the sitter had the baby, and I walked to the dock without looking in the back.\""), .direct("Why did you search how fast a car heats up?", "\"A news story scared me. I looked it up and forgot it, and I never thought it would matter.\""), .direct("You wrote angry messages about custody, didn't you?", "\"I was angry at my ex. I never wanted this, and I never meant for the child to be hurt.\""), .direct("You walked past the rear door, didn't you?", "\"I did not see anything. I wish I had looked, and I would give my life to go back.\""), .direct("Why did you go to the boat?", "\"A friend invited me for the day, and I needed a break. I thought the baby was safe.\""), .direct("What do you want the court to know?", "\"I loved my child. I made the worst mistake of my life, and I will carry it forever.\""), .cross("You locked the van and walked away, didn't you?", "\"Yes. I believed the van was empty.\""), .cross("You spent five hours on a boat, didn't you?", "\"Yes. I did not know the child was in the van.\""), .cross("You typed a search about how fast a closed car heats up, didn't you?", "\"Yes. I read an article that frightened me.\""), .cross("You wrote that raising the child was ruining your life, didn't you?", "\"I wrote it in anger to my ex. I did not mean it.\""), .cross("You had arranged for a sitter, hadn't you?", "\"I thought so. The sitter did not come, and I did not check.\"")],
        openings: ("{D} strapped a 20-month-old into a minivan at a marina lot, cracked no windows, and spent five hours on a friend's boat in 95-degree heat. A dock worker broke a window at mid-afternoon, but the child could not be revived, and {D}'s phone held a search about how fast a closed car heats up.", "{D} was exhausted and believed a sitter had the baby. A forgotten child is a tragedy, and the State must prove {D} knew the child was in that van."),
        closings: ("A closed van in 95-degree heat, five hours on a boat, a search about how fast a car heats up, and angry messages about the burden of a child. The record points to knowledge.", "No sleep, a closed day care, a sitter who did not come, and a parent who did not look in the back. The State must prove {D} knew the child was in the van."),
        timeline: [(-2, "Search for how fast a closed car heats up."), (0, "9:05 a.m.: {DL} leaves the van and boards the boat."), (0, "2:15 p.m.: a dock worker finds the child; death is pronounced at the scene."), (3, "Phone searched under warrant."), (25, "{DL} is indicted.")],
        identified: "A dock worker found the child and the van was traced to {DL}.",
        aggravating: ["The victim was very young", "The defendant took advantage of a position of trust"],
        mitigating: ["No prior criminal record"],
        mood: .divided,
        doctrines: ["burdenOfProof", "priorActs"],
        genders: ["D": .male])

    static let tellerDrawerV1 = SmallCases.make(
        key: "story.tellerDrawer",
        category: .whiteCollar,
        headlines: ["Cash Cassette Goes Missing From Bank ATM Load", "Bank Employee Charged After Audit Finds $41,000 Gap"],
        law: "embezzlement",
        threshold: 3,
        spec: "As an employee of a bank, embezzled $41,000 entrusted to {DL}.",
        ages: 22...36,
        victim: false,
        summary: "On {DATE}, {D}, a bank teller assigned to restock the drive-up ATM, signed out four cash cassettes. At the next audit one cassette, holding $41,000, was empty and had been resealed. The ATM room camera was off for service that week. Soon after, {DL} made large cash payments at a casino. {DL} says the cassette was already short when it came from the courier.",
        state: [E(.document, 3, "Cassette Seal Log", "{DL} signed for four sealed cassettes and returned four resealed ones."), E(.document, 2, "Casino Records", "Cash buy-ins totaling $12,000 in the nine days after the restock."), E(.statement, 2, "Audit Interview", "{DL} could not say who else handled cassette three.")],
        defense: [E(.document, 2, "Courier Manifest", "The manifest lists cassette three as a partial load."), E(.statement, 2, "Shared Keys", "Operations staff also hold ATM room keys.")],
        role: "Branch operations manager",
        exam: [.direct("How does an ATM load work?", "\"A courier brings sealed cassettes, a teller signs for them, loads them, and reseals them after loading.\""), .direct("What did the audit show?", "\"One cassette, holding $41,000, was empty with a new seal on it. The other three were full.\""), .direct("What does the seal log show?", "\"{D} signed for four sealed cassettes and returned four resealed ones. The empty one was cassette three.\""), .direct("What happened with the ATM room camera?", "\"It was off for service that week. We have no footage of the room during the restock.\""), .direct("What did the casino records show?", "\"Cash buy-ins totaling $12,000 in the nine days after the restock. They are in {DL}'s name.\""), .direct("What did {D} say in the audit interview?", "\"That {D.he} could not say who else handled cassette three. {D.He} said the cassette was short when it arrived.\""), .cross("The manifest shows a partial load?", "\"For one cassette. That is still being checked, and I cannot tell you the amount.\""), .cross("Who else holds keys to that room?", "\"Two supervisors do. They enter the room for audits and repairs.\""), .cross("Could a cassette be tampered with before reaching the defendant?", "\"In theory, yes. A courier or someone else could have done it, and we are looking at that.\""), .cross("Did the defendant work any other restocks without problems?", "\"Yes. {D.He} had loaded the ATM many times with clean audits.\""), .cross("Did the defendant cooperate?", "\"Yes. {D.He} answered questions and offered documents.\"")],
        defenseRole: "Armored courier",
        defenseExam: [.direct("What is your work?", "\"I am an armored courier. I deliver sealed cassettes and cash bags to banks and ATMs.\""), .direct("What was in cassette three?", "\"Less than the others. It was marked partial on my sheet, and I noted it at the handoff.\""), .direct("Do you know how much less?", "\"No. I did not count it. We deliver sealed cassettes, and the bank counts.\""), .direct("How is a cassette sealed?", "\"With a numbered tamper seal. The bank signs for the seal number, and a new seal goes on after loading.\""), .direct("Did you speak with {D}?", "\"Briefly, at the drop. {D} signed for four cassettes and everything seemed normal.\""), .direct("Did you tell the defendant about the partial?", "\"I did. I said one was partial, and {D.he} said that was fine.\""), .cross("Did you check the cassette's contents?", "\"No. I only check seal numbers. We never open them.\""), .cross("Could the amount have been wrong at your depot?", "\"Possibly. Loads are made at the vault, and mistakes happen.\""), .cross("Did you write the partial on the manifest?", "\"Yes, on my sheet. I am not sure it matches the bank's manifest.\""), .cross("Did you see the defendant do anything odd?", "\"No. {D.He} seemed careful and followed procedure.\""), .cross("Do you know the defendant personally?", "\"Only from drops. I would call us friendly.\"")],
        theory: ("{D} emptied a cassette and resealed it.", "A short load, shared keys and no camera."),
        allocution: "\"I should never have gone near that money.\"",
        truths: ("A second set of ATM keys was cut at a hardware kiosk, and the receipt was in {DL}'s car.", "The courier's truck GPS showed an unlogged stop of forty minutes before the delivery."),
        defendant: [.direct("Did you empty the cassette?", "\"No. I loaded what I was given. I did not open a sealed cassette and take cash out.\""), .direct("Where did the casino money come from?", "\"My savings and a tax refund. I deposited the refund and drew from savings.\""), .direct("Why did you reseal it?", "\"That is the procedure. After loading, we reseal the cassette and return it for the audit.\""), .direct("Why did the cash go in nine days?", "\"I was having a bad run. I lost more than I planned, and I am ashamed of it.\""), .direct("What about the missing camera?", "\"It was off for service. I did not know, and I did not turn it off.\""), .direct("What do you want the bank to know?", "\"I did not take that $41,000. I made a mistake gambling, and I would never steal from my employer.\""), .cross("You signed for four sealed cassettes, didn't you?", "\"Yes. I signed, and I returned four.\""), .cross("One was empty when audited, wasn't it?", "\"So I am told. It was short when it came.\""), .cross("You spent $12,000 at a casino, didn't you?", "\"Over nine days, yes. It was my money.\""), .cross("You cannot show where that money came from, can you?", "\"I have the refund and my savings. I did not keep a ledger.\""), .cross("The camera was off, wasn't it?", "\"Yes. I did not touch it.\"")],
        openings: ("{D}, a bank teller assigned to restock the drive-up ATM, signed out four cash cassettes. At the audit one cassette holding $41,000 was empty and resealed, the room camera was off, and {D} made $12,000 in casino buy-ins soon after.", "The cassette was already short when it came from the courier, and {D} loaded what was given. A gambler is not a thief, and a missing camera cannot convict anyone."),
        closings: ("Four cassettes signed out, one empty and resealed, a camera off, and $12,000 at a casino in nine days. The money and the seal both lead to {D}.", "A partial load noted by the courier, a camera off for service, and two supervisors with keys. The State cannot show {D} emptied that cassette."),
        timeline: [(-3, "ATM room camera goes offline for service."), (0, "Morning: {DL} signs out four cassettes."), (9, "Casino buy-ins total $12,000."), (14, "Audit finds cassette three empty.")],
        identified: "The seal log tied {DL} to the empty cassette.",
        mitigating: ["No prior criminal record"],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let mailedPillsV1 = SmallCases.make(
        key: "story.mailedPills",
        category: .drugs,
        headlines: ["Leaking Parcel Leads Inspectors to Fentanyl Pills in Apartment Locker", "Locker Camera Catches Pickup of Drug Package"],
        law: "traffickingOpioid",
        threshold: 7,
        spec: "Trafficked in an opioid by possessing 4 grams or more but less than 14 grams of fentanyl, in the form of pressed pills, on {DATE}.",
        ages: 21...38,
        victim: false,
        summary: "A delivery driver reported a shoebox that had split open at a parcel locker bank in an apartment complex, spilling green pills. Inspectors replaced the box with a sealed copy, added a tracker, and obtained a warrant. Two days later, on {DATE}, {D} used a code to open the locker and left with the box. The lab later found 80 pills with 7.2 grams of fentanyl mixture. The locker was assigned to a unit {D} does not live in. {DL} says a neighbor asked {D.him} to bring in a package.",
        state: [E(.forensic, 3, "Lab Report", "80 pills weighing 7.2 grams of fentanyl mixture."), E(.video, 2, "Locker Camera", "{D} opens the locker with a code and takes the shoebox."), E(.digital, 2, "Pickup Code Log", "The code was texted to a number registered to {D}.")],
        defense: [E(.digital, 2, "Neighbor Text", "A text from the unit holder asks {DL} to grab a package."), E(.document, 1, "Shipping Label", "The label lists a name {DL} does not use.")],
        role: "Postal inspector",
        exam: [.direct("How did this begin?", "\"A delivery driver reported a shoebox that had split open at a parcel locker bank in an apartment complex, spilling green pills.\""), .direct("What did inspectors do?", "\"We replaced the box with a sealed copy, added a tracker, and obtained a warrant before anyone came for it.\""), .direct("What happened at the pickup?", "\"{D} entered the code, took the box, and walked to the parking lot. The locker camera records the whole thing.\""), .direct("How did {D} get the code?", "\"The pickup code log shows it was texted to a number registered to {D.him}, a few hours before the pickup.\""), .direct("What did the lab find?", "\"80 pills weighing 7.2 grams of a fentanyl mixture. The pills were counterfeit and extremely dangerous.\""), .direct("Was the locker in the defendant's name?", "\"It was assigned to another unit, in a building where {D.he} does not live.\""), .cross("Did the defendant open the box before the arrest?", "\"Not before the arrest. The box was still taped shut when we stopped {D.him} at the car.\""), .cross("Did the defendant try to run or hide it?", "\"No. {D.He} walked to the lot in the open and stopped when we approached.\""), .cross("Did you identify the sender?", "\"Not yet. The return address was false, and we are still tracing it.\""), .cross("Did the defendant explain the pickup?", "\"Yes. {DL} said a neighbor asked for a favor and sent the code by text.\""), .cross("Did you speak to the neighbor?", "\"We located the unit holder. I cannot describe more here.\"")],
        defenseRole: "Apartment leasing agent",
        defenseExam: [.direct("What do you do at the complex?", "\"I am a leasing agent. I manage move-ins, lockers, and resident requests at the apartment complex.\""), .direct("Whose unit owns the locker?", "\"A resident on the third floor. The locker is assigned to that unit, and the code goes to that resident.\""), .direct("Did {D} live there?", "\"{D.He} lived in another building, a few blocks away. {D} was a friend of the resident, I believe.\""), .direct("How do residents get locker codes?", "\"By text, when a parcel arrives. Residents sometimes share codes with friends who help pick up.\""), .direct("Is that allowed?", "\"Not officially. It happens often. Residents ask neighbors and friends to pick up when they are away.\""), .direct("Did you ever see the defendant at the lockers?", "\"A few times, helping carry boxes. {D.He} was friendly with staff and residents.\""), .cross("Did you know the defendant had the code?", "\"No. I did not know until the sheriff called.\""), .cross("Did the resident tell you the defendant would pick up?", "\"No. Residents do not tell us. They just send the code.\""), .cross("Did you ever see the box in question?", "\"No. I never saw the shoebox before the inspectors showed it to me.\""), .cross("How long has the defendant been around the complex?", "\"About a year, on and off. I would call {DF} a regular visitor.\""), .cross("Do you like {D}?", "\"I do. {D.He} has always been polite.\"")],
        theory: ("{D} collected a box of fentanyl pills from a locker.", "A neighbor's errand."),
        allocution: "\"I never should have taken a package I did not know.\"",
        truths: ("A second box with the same return address was found empty under {DL}'s bed.", "The unit holder was later found with a notepad listing other parcels' tracking numbers."),
        defendant: [.direct("Why did you take the box?", "\"My neighbor asked me. I had no idea what was in it, and I thought it was a regular parcel.\""), .direct("Did you check the label?", "\"No. It was taped shut, and I did not look at the label. I just followed the neighbor's instructions.\""), .direct("You got the code by text?", "\"Yes, from the neighbor. The neighbor was out of town and asked me to grab the box.\""), .direct("Why not ask what was inside?", "\"It was a favor. I did not want to pry, and I thought the neighbor was waiting on something personal.\""), .direct("What did you do when the inspectors stopped you?", "\"I told them the truth right away. I gave them the neighbor's name and my phone.\""), .direct("What do you want the court to know?", "\"I did a favor for someone I trusted. I did not know what was in the box, and I would never carry fentanyl.\""), .cross("You took the box from a locker that was not yours, didn't you?", "\"Yes, at the neighbor's request. I had the code.\""), .cross("You walked right to the parking lot, didn't you?", "\"Yes. I was headed to my car and then to the neighbor's place.\""), .cross("80 pills of fentanyl were in the box, weren't they?", "\"So the lab says. I did not know.\""), .cross("You did not ask what was inside, did you?", "\"No. In hindsight, yes.\""), .cross("The code came from a text to your number, didn't it?", "\"Yes. The neighbor forwarded it to me.\"")],
        openings: ("A delivery driver found a shoebox split open at a parcel locker bank, spilling green pills. Inspectors replaced it with a sealed copy and a tracker, and two days later {D} opened the locker with a code and left with the box, which held 80 fentanyl pills.", "A neighbor asked {D} for a favor, and {D} had no idea what was in the box. Picking up a parcel for a neighbor is not drug trafficking."),
        closings: ("A code texted to {D}'s number, a locker camera showing the pickup, and 7.2 grams of fentanyl mixture. {D} took the box from a locker that was not {D}'s own.", "A favor for a neighbor, a box taped shut, and a code from a text. The State must prove {D} knew what was inside, and nothing says {D} did."),
        timeline: [(-4, "A driver finds a split box in the locker bank."), (-2, "Inspectors swap in a sealed box and get a warrant."), (-1, "A text with the locker code reaches {DL}'s phone."), (0, "4:20 p.m.: {DL} takes the box and is arrested.")],
        identified: "Arrested during a controlled delivery to the locker.",
        aggravating: ["The offense involved a large quantity of controlled substance"],
        mitigating: ["The defendant has accepted responsibility", "The defendant is young"],
        mood: .wantsConviction,
        doctrines: ["searchSeizure", "burdenOfProof", "lesserIncluded"])

    static let fountainDestroyedV1 = SmallCases.make(
        key: "story.fountainDestroyed",
        category: .property,
        headlines: ["Chain Yanked Through Park Fountain, Town Loses Bronze Heron", "Livestream Shows Truck Pulling Down Fountain Statue"],
        law: "injuryRealProperty",
        threshold: 7,
        spec: "Willfully and wantonly injured real property of {V}, a town, causing damage of $34,000, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "On {DATE}, a group chained a bronze heron statue in a town park fountain to a pickup and pulled it off its base, cracking the basin and the supply pipe. A friend's livestream showed {D} at the scene. {DL} says {D.he} was filming and told them to stop.",
        state: [E(.video, 3, "Livestream Clip", "{D} stands next to the chain as the truck pulls."), E(.physical, 3, "Tow Chain", "A chain with {D}'s prints was in the bed of the pickup that pulled the statue.", .search), E(.document, 2, "Repair Estimate", "$34,000 for the basin, pipe and statue.")],
        defense: [E(.statement, 1, "Filming", "{DL} says {D.he} was filming and trying to stop it.")],
        role: "Parks director",
        exam: [.direct("What was damaged at the fountain?", "\"The basin, the supply pipe, and the bronze heron. A truck pulled the heron off its base with a chain.\""), .direct("How much is the damage?", "\"$34,000, according to the repair estimate, for the basin, the pipe, and the statue.\""), .direct("What tied {D} to it?", "\"The livestream and the chain. {D} stands next to the chain as the truck pulls, and {D.his} prints were on a chain in the truck bed.\""), .direct("How did the pull happen?", "\"A group chained the heron to a pickup and drove off, cracking the basin and the supply pipe.\""), .direct("Where does the livestream come from?", "\"A friend's phone, posted live that night. We obtained the full clip from the platform.\""), .direct("What was the public effect?", "\"The fountain flooded part of the park. The town had to shut the supply and close the area.\""), .cross("Did the defendant drive the pickup?", "\"No. {D.He} did not drive. The driver is someone else, and we are still working to identify that person.\""), .cross("Does the video show who hooked the chain?", "\"It does not. The video shows the chain and the truck, and we cannot see who attached it.\""), .cross("Did the defendant yell anything on the clip?", "\"I heard raised voices. I could not make out what {D.he} said, and I would not guess.\""), .cross("How did the defendant's prints come to be on the chain?", "\"I cannot say. Prints do not tell me when the chain was touched or why.\""), .cross("Did the defendant cooperate with you?", "\"Yes. {D.He} gave a statement and explained why {D.he} was there and what {D.he} did.\"")],
        defenseRole: "Friend who streamed",
        defenseExam: [.direct("How do you know {D}?", "\"We are friends. We were out together that night, and I was filming a livestream.\""), .direct("What did the defendant do?", "\"{D} held my phone light and yelled to stop. {DF} did not want them to pull the statue.\""), .direct("Did the defendant touch the chain?", "\"Once, to move it off the road. A car was coming, and {D.he} dragged the chain aside.\""), .direct("Who drove the pickup?", "\"Someone from the group. I will not say who, and I know that is hard.\""), .direct("How did the defendant act when the truck pulled?", "\"Stunned. {D.He} stepped back and covered {D.his} mouth, and then said we should leave.\""), .direct("What happened after?", "\"We drove away. I was scared, and {D.he} was quiet the whole way.\""), .cross("Why did you stream?", "\"For fun. I regret it. It shows my friend at the worst moment.\""), .cross("Did the defendant try to stop the truck?", "\"{D.He} yelled. {D.He} did not stand in front of it.\""), .cross("Did you tell the group to stop?", "\"I did not. I only filmed.\""), .cross("Are you protecting {D}?", "\"I am telling the truth. I would say the same of anyone.\""), .cross("Were you charged?", "\"Not yet. I am cooperating.\"")],
        theory: ("{D} helped tear down a town fountain.", "A bystander who tried to stop it."),
        allocution: "\"I should have walked away.\"",
        truths: ("{DL} sent a photo of the chain link to the group that night with the words 'pull it.'", "{DL} is heard on the clip shouting that the water main would burst."),
        defendant: [.direct("Did you pull the statue?", "\"No. I held a light for the stream. I did not hook the chain or drive the truck.\""), .direct("Why was your print on the chain?", "\"I moved it out of the road. A car was coming, and I grabbed the chain and dragged it aside.\""), .direct("You were there for all of it, weren't you?", "\"Yes. I was there from the start, trying to talk them out of it.\""), .direct("Why did you not leave?", "\"I was trying to stop them. I thought if I stayed, I could talk them down.\""), .direct("What did you say?", "\"I told them to stop, and I said the statue was not worth it. They did not listen.\""), .direct("What do you want the town to know?", "\"I truly am sorry. I should have left, and I should have called someone.\""), .cross("The livestream shows you next to the chain, doesn't it?", "\"Yes. I was holding a light and standing nearby.\""), .cross("Your prints were on the chain, weren't they?", "\"Yes. I moved it, as I said.\""), .cross("You never called the police, did you?", "\"No. I wish I had. I was scared.\""), .cross("You stayed for the entire event, didn't you?", "\"Yes. I did not leave until it was over.\""), .cross("You knew what they planned, didn't you?", "\"I learned it as it happened. I tried to stop it.\"")],
