        summary: "On {DATE}, during a music video shoot in a rented warehouse, a performer fired a prop pistol toward the camera for a scripted shot. A live round struck {V}, the lighting gaffer, who died on the floor. {D}, the prop master, loaded and secured every gun on the shoot. Investigators found a live cartridge mixed in a bag of blanks. {DL} says the case was unlocked and another crew member had been handling it.",
        state: [E(.physical, 3, "Live Cartridge", "The round matches a box in {D}'s prop case."), E(.document, 3, "Loading Log", "{D} signed the log for the pistol that morning."), E(.statement, 2, "Crew Text", "A crew member texted {D} about a live round in the blank bag the day before."), E(.document, 2, "Range Receipt", "A receipt for live ammunition in {D}'s name.")],
        defense: [E(.digital, 2, "Case Access Photo", "A phone photo shows the prop case open and unattended at 7 a.m."), E(.statement, 2, "Performer Handling", "The performer admits taking the pistol out of the case without {DL}."), E(.document, 1, "Hiring Notes", "Producers hired {D} as both prop master and safety lead.")],
        role: "Firearms examiner",
        exam: [.direct("What did you find?", "\"A live cartridge in the pistol. Its twin was in the prop case, matching a box in the case.\""), .direct("Who loaded the pistol?", "\"{D}'s signature is on the loading log for that pistol that morning.\""), .direct("Could someone else have swapped the rounds?", "\"If the case was open, yes. The case was not locked during part of the morning.\""), .direct("Was the log checked later?", "\"No one rechecked it after the morning. After the initial loading, no one verified the pistol again.\""), .direct("What did the range receipt show?", "\"A receipt for live ammunition in {D.his} name. It is part of why we looked at the case.\""), .direct("What did the crew text show?", "\"A crew member texted {D.him} about a live round in the blank bag the day before the shoot.\""), .cross("Did anyone else handle the pistol?", "\"The performer picked it up before the shot. Others may have handled the case.\""), .cross("Was the case open at any time?", "\"Part of the morning. A production assistant says it sat open by the craft table for an hour.\""), .cross("Does a loading log prove who loaded it?", "\"It shows who signed. It does not prove who touched the rounds later.\""), .cross("Did {D} cooperate?", "\"Yes. {D.He} handed over the log, the case, and the phone, and answered every question.\""), .cross("Did the defendant tell the crew about the live round?", "\"The text suggests a warning was sent. I cannot say what was done with it.\"")],
        defenseRole: "Production assistant",
        defenseExam: [.direct("What is your job?", "\"I am a production assistant. I run errands, set up tables, and help wherever the crew needs a hand.\""), .direct("Who had the prop case that morning?", "\"It sat open by the craft table for an hour. People walked by and grabbed coffee next to it.\""), .direct("Did you see anyone touch the pistol?", "\"The performer picked it up. I saw that, and a few others looked at it.\""), .direct("Where was {D} during that hour?", "\"Setting up another shot in the back of the warehouse. {D} was out of sight of the table.\""), .direct("How did the defendant handle the guns normally?", "\"Carefully. {DF} checked each round and kept notes. I thought {DF} was the safest person on set.\""), .direct("What happened after the shot?", "\"Chaos. {V} fell, and people screamed. {DF} ran to {V} and called for help.\""), .cross("Did you see anyone swap rounds?", "\"No. I did not see anyone open the bag or swap anything.\""), .cross("Did you hear about a live round the day before?", "\"I heard something in passing. I did not know the details.\""), .cross("How many people walked past the case?", "\"A dozen, maybe more. I did not count.\""), .cross("Was the case locked?", "\"Not while it sat there. {D.He} locked it later.\""), .cross("Are you close to the defendant?", "\"We work together. I would say the same about anyone.\"")],
        theory: ("{D} let a live round into a prop pistol.", "An unlocked case and a pistol handled by others."),
        allocution: "\"I loaded those guns myself. I will carry this forever.\"",
