        defendant: [.direct("How did you load the pistol?", "\"With blanks from a labeled bag. I loaded each round by hand and checked it.\""), .direct("Did you check each round?", "\"I checked at 7. After that, the case was out of my sight for a while.\""), .direct("You bought live rounds, didn't you?", "\"For target practice. They never went in the case, and I kept them at home.\""), .direct("You had a warning text, didn't you?", "\"I thought it was handled. I told the crew member to get rid of the round, and I assumed it was done.\""), .direct("How did you feel when {V} fell?", "\"I could not breathe. I ran over, called for help, and held {V}'s hand.\""), .direct("What do you want {V}'s family to know?", "\"I am so sorry. I would give anything to change that morning, and I check every round forever now.\""), .cross("Your signature is on the loading log, isn't it?", "\"Yes. I signed after I loaded the pistol.\""), .cross("A live cartridge was in the pistol, wasn't it?", "\"So the examiner says. I do not know how it got there.\""), .cross("A box of live rounds in your name was bought at a range, wasn't it?", "\"Yes. That was for my own practice.\""), .cross("You did not recheck the pistol before the shot, did you?", "\"No. I checked at 7. I should have checked again.\""), .cross("You were told a live round was in the blank bag, weren't you?", "\"Yes. I thought it had been removed.\"")],
        openings: ("A performer fired a prop pistol toward the camera at a music video shoot, and a live round struck {V}, the lighting gaffer, who died on the floor. {D}, the prop master, signed the loading log, and a live cartridge matching a box in {D}'s prop case was in the pistol.", "The prop case sat open by the craft table for an hour, and others handled it. A prop master who loaded blanks and checked at 7 is not the one who put a live round in."),
        closings: ("A live round, {D}'s signature on the log, live ammunition in {D}'s name, and a warning text the day before. A prop master carries the responsibility.", "An open case, a crowded set, and a prop master whose checks were sound at 7. The State must prove {D} loaded a live round."),
        timeline: [(-1, "A crew member texts about a live round in the blank bag."), (0, "7 a.m.: {DL} loads the pistol; the case is left open."), (0, "2:40 p.m.: the shot is fired and {VL} is killed."), (60, "State lab matches the round to a box in the case."), (90, "{DL} is charged.")],
        identified: "{DL} was the prop master in charge of every firearm on the shoot.",
        mitigating: ["No prior criminal record"],
        mood: .divided,
        doctrines: ["burdenOfProof"])

    static let sergeantTicketCashV1 = SmallCases.make(
