        state: [E(.digital, 3, "Wire Recording", "The owner says 'for keeping the block quiet,' and {D} says 'understood.'"), E(.document, 3, "Patrol Logs", "No after-hours checks were logged at the bar for six weeks."), E(.statement, 2, "Bar Owner", "The owner says the payment bought quiet nights.")],
