        defense: [E(.statement, 1, "Wrong Wall", "{DL} says the tenant pointed to the north wall.")],
        role: "Public works director",
        exam: [.direct("What was lost?", "\"A painted sign from the 1920s on the north wall of a town-owned brick building. It was a faded mural, but it was original.\""), .direct("Who washed the wall?", "\"{D}'s crew. A neighbor photographed the truck with the company logo and a power washer at the north wall.\""), .direct("Who hired the crew?", "\"The building's tenant. The tenant wanted graffiti washed off and hired {DL}'s company for the work.\""), .direct("What does the invoice show?", "\"{D.his} company billed for 'north and east walls.' The north wall is where the mural was.\""), .direct("What would it cost to restore?", "\"$9,200 to repaint the sign. That is the estimate we received from a restoration painter.\""), .direct("Was the wall marked as historic?", "\"No sign said so. The mural was faded, and nothing on the wall labeled it.\""), .cross("Did the tenant choose the walls?", "\"The tenant asked for graffiti removal. I do not know which walls the tenant named.\""), .cross("Was the north wall covered in graffiti?", "\"Some. The east wall had more, as I recall.\""), .cross("Would a crew know it was a mural?", "\"A faded painted sign can look like old paint. I can see how a crew might treat it as dirt.\""), .cross("Did {D} cooperate?", "\"Yes. {D.He} came forward, apologized, and offered to pay for part of the restoration.\""), .cross("Did the town record the mural somewhere?", "\"In our files, yes. Nothing was posted at the building.\"")],
        defenseRole: "Building tenant",
        defenseExam: [.direct("What is your role?", "\"I am the building's tenant. I rent the ground floor and asked for graffiti to be washed off.\""), .direct("Which wall did you ask to be cleaned?", "\"The east wall, with the graffiti. That is the wall I meant.\""), .direct("Did you tell the crew the north wall?", "\"I may have waved that way. I was on the phone and pointed around the corner.\""), .direct("How did you hire the crew?", "\"I called {D}'s company and said I needed graffiti removed. We agreed on a price over the phone.\""), .direct("What were you doing during the wash?", "\"Working inside. I did not watch the whole thing, and I did not see which wall they hit.\""), .direct("How did you feel when you learned?", "\"Horrified. I did not know about the mural, and I never wanted it ruined.\""), .cross("Did you give a written order?", "\"No. It was a phone call and a quick wave.\""), .cross("Did you tell the crew about the mural?", "\"No. I did not know about it.\""), .cross("Did you check the invoice?", "\"Not closely. I paid when I saw 'north and east walls.'\""), .cross("Did you complain about the north wall?", "\"Not until the town called me.\""), .cross("Do you blame {D}?", "\"I blame myself too. I should have been clearer.\"")],
        theory: ("{D}'s crew destroyed a historic mural.", "A work order for the wrong wall."),
        allocution: "\"I'm sorry for what we took off that wall.\"",
        truths: ("The town clerk told {DL} by phone not to touch the north wall.", "The tenant's work order named the wrong wall in writing."),
        defendant: [.direct("Did you wash the mural?", "\"Yes, but I did not know. My crew power-washed the north wall because the tenant pointed that way.\""), .direct("Who told you which wall?", "\"The tenant. The tenant said to clean the walls with graffiti and waved toward the corner.\""), .direct("Did anyone tell you about the mural?", "\"No one said a word. A message came in later that I did not return.\""), .direct("Did you look at the wall first?", "\"It was dirty brick. The paint was faded, and it looked like old stain.\""), .direct("What did you do when you learned about the mural?", "\"I came forward as soon as I heard and offered to help pay for the restoration. I felt terrible about it.\""), .direct("What do you want the town to know?", "\"I feel awful about it. I never meant to destroy history, and I will help however I can.\""), .cross("You billed for the north and east walls, didn't you?", "\"Yes, that is what the tenant wanted cleaned, and that is what I billed, without thinking about anything historic.\""), .cross("You power-washed a painted sign off the north wall, didn't you?", "\"Yes, though I did not see a sign anywhere on that wall. To my eye it was only old brick and stain.\""), .cross("You did not return a message, did you?", "\"I did not return it. I assumed it was routine paperwork, and I regret that choice more than I can say.\""), .cross("You did not ask which walls before starting, did you?", "\"I asked the tenant, and the answer was a wave of the hand toward the corner. I should have asked again.\""), .cross("A crew should check for paint before stripping it, shouldn't they?", "\"Yes, I should have looked much harder at that wall before I put a power washer to it.\"")],
        openings: ("A crew hired to wash graffiti off a town-owned brick building also stripped a painted-sign mural from the 1920s off the north wall. A neighbor photographed the crew's truck, which belongs to {D}, and the invoice lists the north and east walls.", "The tenant pointed at the wrong wall, and nothing on the brick said historic. A crew that washed dirty brick is careless, not a vandal."),
        closings: ("A truck with {D}'s logo, a power washer at the north wall, an invoice for both walls, and a 1920s sign gone. {D} washed the mural off.", "A tenant's wave, a faded sign that looked like dirt, and an honest crew. The State must prove {D} meant to damage the mural."),
        timeline: [(-5, "The tenant orders a graffiti wash."), (0, "Morning: the crew washes the north wall."), (1, "The town finds the sign gone."), (4, "{DL} is identified from the invoice.")],
        identified: "An invoice and a neighbor's photographs.",
        mood: .divided,
        doctrines: ["mistakeOfFact"])

    static let ambulanceEntryBlockV1 = SmallCases.make(
        key: "story.ambulanceEntryBlock",
        category: .publicOrder,
        headlines: ["Demonstrators Chain Gate at Rural EMS Station", "Ambulance Held Nine Minutes at Locked Gate"],
        law: "disorderly",
        threshold: 6,
        spec: "Disturbed the peace by blocking an emergency vehicle exit, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "Demonstrators chained the main gate of a rural EMS station on {DATE}. A crew called to a farm accident waited nine minutes before leaving. {D} was the one holding the lock. {DL} says a side gate was open.",
        state: [E(.video, 3, "Station Camera", "{D} stands at the chained gate holding the padlock."), E(.document, 3, "Dispatch Log", "A nine-minute gap between the call and the crew's departure."), E(.statement, 2, "EMS Captain", "The captain says the side gate was too narrow for the ambulance.")],
        defense: [E(.statement, 1, "Side Gate", "{DL} says a side gate stayed open.")],
        role: "EMS captain",
        exam: [.direct("What happened at the gate?", "\"Demonstrators chained the main gate of our rural EMS station. Our rig could not get out until the chain came off.\""), .direct("What call did you receive?", "\"A farm accident. The dispatcher sent us, and the crew was ready to leave within seconds.\""), .direct("How long did it take?", "\"Nine minutes from the call to the crew's departure. The dispatch log shows the gap.\""), .direct("Who held the padlock?", "\"{D}. The station camera shows {DL} standing at the chained gate holding the padlock.\""), .direct("Was the side gate open?", "\"It was, but too narrow for the ambulance. A person could walk through it, and the rig could not.\""), .direct("How serious was the patient?", "\"A broken leg, stable. The patient waited longer, and we were glad it was not worse.\""), .cross("Did {D} refuse to unlock?", "\"I do not recall a refusal. {D.He} was among several demonstrators, and I spoke to a few.\""), .cross("Did you ask the demonstrators to move?", "\"Yes. I asked, and a few seemed surprised that a call had come in.\""), .cross("Did anyone stop you from using the side gate?", "\"No. It was open, but the ambulance could not fit.\""), .cross("How wide is the side gate?", "\"Narrower than the rig. I did not measure it.\""), .cross("Did anyone get hurt because of the delay?", "\"The patient was stable. I cannot say there was lasting harm.\"")],
        defenseRole: "Demonstration organizer",
        defenseExam: [.direct("What is your role?", "\"I organized the demonstration. We came to protest a state decision, and we chained the main gate as a symbol.\""), .direct("Was a way out left open?", "\"We left the side gate unlocked. We wanted to avoid blocking emergency access.\""), .direct("Could an ambulance pass?", "\"I did not measure it. I thought a smaller vehicle could, and I did not think about the rig.\""), .direct("Did you know about the call?", "\"Not at first. We were chanting and singing, and no one on the line came to tell us a call had come in.\""), .direct("What happened when you heard?", "\"We scrambled. Someone said an ambulance was waiting, and {D} went to find the key.\""), .direct("Who held the padlock?", "\"{DF}. {DF} volunteered to hold it as part of the protest, and it was in {DF}'s hand when the call came.\""), .cross("Did you plan to block the main gate?", "\"Yes. Blocking the main gate was the whole point of the protest, so we chained it before the first speaker.\""), .cross("Did you tell the EMS crew in advance?", "\"No. We did not warn the crew in advance, and in hindsight we should have called the station ahead of time.\""), .cross("Did you check whether the side gate was wide enough?", "\"No, I did not measure it. I should have walked the side gate with a tape before we chained anything.\""), .cross("How long did the chain stay on?", "\"Until the key was found and brought over. It took several minutes, and that delay is on us.\""), .cross("Do you regret the protest?", "\"I regret the delay that day very much. I do not regret the cause we were standing up for.\"")],
        theory: ("{D} held a chained gate shut on an ambulance.", "A protest that left a way out."),
        allocution: "\"I did not think it through.\"",
        truths: ("A deputy handed {DL} a written order to unlock the gate, and {DL} waited four minutes.", "Dispatch audio caught {DL} saying 'unlocking now' within a minute of the call."),
        defendant: [.direct("Did you hold the lock?", "\"Yes, as part of the protest. I volunteered to hold the padlock, and I stood by the gate.\""), .direct("Did you know of the call?", "\"Not at first. We were singing, and the ambulance call was a surprise.\""), .direct("Why did it take so long to unlock?", "\"I was getting the key. I had left it with a friend, and it took time to find.\""), .direct("Was the side gate wide enough?", "\"I thought so. It looked wide enough for a smaller vehicle, and I did not think about the rig.\""), .direct("What did you do when you learned?", "\"I rushed to find the key and told the crew we would open it. I felt awful.\""), .direct("What do you want the EMS crew to know?", "\"I am sorry. I never meant to delay anyone who needed help.\""), .cross("You stood at the gate holding the padlock, didn't you?", "\"Yes. The camera shows it.\""), .cross("The rig could not pass through the side gate, could it?", "\"So the captain says. I did not measure.\""), .cross("A crew waited nine minutes, didn't it?", "\"So the log says. I am sorry for that.\""), .cross("You chose to chain a gate to an EMS station, didn't you?", "\"Yes. It was a protest, and I regret where we did it.\""), .cross("You did not warn anyone, did you?", "\"No. We did not.\"")],
        openings: ("Demonstrators chained the main gate of a rural EMS station, and a crew called to a farm accident waited nine minutes before leaving. {D} was the one holding the padlock, and the side gate was too narrow for the ambulance.", "{D} was holding the lock as part of a protest and did not know a call had come in. A side gate was left open, and {D} rushed to find the key."),
        closings: ("A chained gate, a padlock in {D}'s hand, a side gate too narrow for the rig, and nine minutes lost. {D} knew where the gate led.", "A protest, a side gate left open, and a key that took time to find. The State must prove {D} knew a call was waiting and kept the chain on."),
        timeline: [(0, "10 a.m.: the gate is chained."), (0, "10:20 a.m.: the farm accident is reported."), (0, "10:29 a.m.: the chain comes off."), (0, "11 a.m.: {DL} is cited.")],
        identified: "A station camera.",
        mood: .divided,
        doctrines: ["relevance"])

    static let fourthDwiV1 = SmallCases.make(
        key: "story.fourthDwi",
        category: .traffic,
        headlines: ["Clerk's 911 Call Leads to Fourth DWI Charge at Gas Pump", "Driver Slumped at Pump Faces Habitual Impaired Driving"],
        law: "habitualDWI",
        threshold: 7,
        spec: "Drove while impaired, having been convicted of three prior impaired-driving offenses within ten years, on {DATE}.",
        ages: 28...62,
        victim: false,
        summary: "A gas station clerk called 911 on {DATE} about a driver who pulled in too fast and sat slumped at the pump with the engine running. A deputy found {D} behind the wheel, smelling of alcohol, and a breath test read 0.14. A records check showed three impaired-driving convictions in the last ten years. {DL} says {D.he} is diabetic and was only weak and sleepy.",
        state: [E(.forensic, 3, "Breath Test", "0.14 on the station instrument."), E(.document, 3, "Prior Convictions", "Three impaired-driving convictions within ten years."), E(.video, 2, "Gas Station Camera", "The car swerves over the curb and stops across two pumps.")],
        defense: [E(.statement, 1, "Low Blood Sugar", "{DL} says {D.he} is diabetic and felt faint.")],
        role: "Sheriff's deputy",
        exam: [.direct("What did you find at the pump?", "\"{D} slumped behind the wheel with the engine running, and a smell of alcohol. The clerk had called 911.\""), .direct("What did the gas station camera show?", "\"The car swerving over the curb and stopping across two pumps. It pulled in too fast.\""), .direct("What was the reading?", "\"0.14 on the station instrument, taken at the jail after the arrest and after the required observation period.\""), .direct("What did the records check show?", "\"Three impaired-driving convictions within the last ten years. This would have been a fourth, and I noted it in my report.\""), .direct("Did {D} say anything about medical conditions?", "\"{D.He} told me {D.he} is diabetic and said {D.he} was only weak and sleepy, not drunk, when I first spoke with {D.him}.\""), .direct("Did you check blood sugar?", "\"Paramedics did. I called them to the scene, they examined {DL}, and I left the medical questions to them.\""), .cross("Is the defendant diabetic?", "\"{D.He} told me so at the scene. I did not verify it myself, and I did not see a medical bracelet.\""), .cross("Could low blood sugar cause slumping?", "\"It can. A diabetic with low blood sugar can seem drunk, and I considered that.\""), .cross("What did the paramedics tell you?", "\"They checked and said what they found. I do not remember the number.\""), .cross("Did the defendant resist?", "\"No. {D.He} was cooperative and polite throughout, answered what I asked, and gave me no trouble at any point.\""), .cross("Did the defendant walk steadily?", "\"Not entirely. {D.He} swayed a little on the walking test and stepped off the line once, though {D.he} tried.\"")],
        theory: ("{D} drove drunk a fourth time.", "A diabetic driver with low blood sugar."),
        allocution: "\"I have let everyone down. I need help.\"",
        truths: ("A half-empty flask was under the driver's seat.", "The paramedics' glucose reading was 48 at the scene."),
        defendant: [.direct("Had you been drinking?", "\"One drink with dinner. I do not usually drink, and that evening I had one.\""), .direct("Why were you slumped?", "\"My sugar dropped. I am diabetic, and a low can make me weak and sleepy.\""), .direct("What about the 0.14?", "\"I did not feel it. I do not know how it was that high, and I was not drunk.\""), .direct("What about your three priors?", "\"I know. This is different. I was not impaired by alcohol that night.\""), .direct("Why did you pull in so fast?", "\"I was feeling dizzy and wanted to stop. I came in too quickly and hit the curb.\""), .direct("What do you want the deputy to know?", "\"I should not have been driving while I felt weak. I did not mean to drive drunk.\""), .cross("You had three prior impaired-driving convictions, didn't you?", "\"Yes. They are in my past, and I understand how it looks.\""), .cross("Your breath test read 0.14, didn't it?", "\"So I am told. I do not understand it.\""), .cross("You smelled of alcohol, didn't you?", "\"I had a drink with dinner. That is what the deputy smelled.\""), .cross("You drove to the pump with the engine running, didn't you?", "\"Yes. I stopped and did not turn it off.\""), .cross("You drove while feeling weak, didn't you?", "\"Yes. I should not have.\"")],
        openings: ("A gas station clerk called 911 about a driver who pulled in too fast and sat slumped at the pump with the engine running. A deputy found {D} behind the wheel smelling of alcohol, the breath test read 0.14, and {D} has three impaired-driving convictions in ten years.", "{D} is diabetic and was weak and sleepy, not drunk. A low blood sugar can mimic impairment, and {D} had one drink with dinner."),
        closings: ("A slumped driver at the pump, a 0.14 on the instrument, a smell of alcohol, and three prior convictions in ten years. {D} has been in this position before.", "A diabetic with a low blood sugar, one drink with dinner, and a car that stopped at a pump. The State must prove alcohol, not illness, impaired {D}."),
        timeline: [(0, "9:50 p.m.: the car swerves into the gas station."), (0, "9:58 p.m.: the clerk calls 911."), (0, "10:20 p.m.: a deputy arrests {DL}."), (0, "11:10 p.m.: the breath test.")],
        identified: "A clerk's 911 call and a records check.",
        aggravating: ["The defendant was impaired at the time of the offense"],
        mood: .wantsConviction,
        doctrines: ["priorRecord"],
        genders: ["V": .male])

    static let taserMistakeV1 = SmallCases.make(
        key: "story.taserMistake",
        category: .violent,
        headlines: ["Deputy Fires Pistol Instead of Taser in Backyard Foot Chase", "Teen Dies After Mix-Up During Night Arrest"],
        law: "invManslaughter",
        threshold: 4,
        spec: "By culpable negligence, unintentionally killed {V} by firing a handgun believing it was a Taser.",
        ages: 44...52,
        victim: true,
        summary: "On {DATE}, at 11 p.m., deputies chased {V}, 19, through backyards after a report of a stolen scooter. {V.He} climbed a fence and turned toward {D}, a 22-year veteran, who yelled 'Taser!' and fired once. It was {D.his} pistol. {V} died in the yard. A body camera captured {DL} saying 'Oh no. Oh no.' {DL} carried the Taser on the same side as the pistol that night. {DL} says it was a horrible mistake in the dark.",
        state: [E(.video, 3, "Body Camera", "{DL} shouts 'Taser' and a gunshot follows."), E(.document, 2, "Holster Photos", "The Taser and pistol sat on the same hip, both with dark grips."), E(.document, 2, "Training Records", "{DL} completed the use-of-force course four years earlier.")],
        defense: [E(.document, 2, "Weapon Confusion Research", "Studies on officers mistaking a pistol for a Taser under stress."), E(.video, 1, "Dark Yard", "The yard has no light and {V} turns suddenly.")],
        role: "Use-of-force instructor",
        exam: [.direct("What does the department require for carrying a Taser?", "\"The Taser goes on the support side, away from the pistol, in a bright holster. That rule exists to prevent this mistake.\""), .direct("What did the body camera show?", "\"It shows {D} yelling 'Taser' and a gunshot following. {V} was shot and died in the yard.\""), .direct("How was {D} carrying the Taser that night?", "\"On the same hip as the pistol, with both grips dark. The holster photos show them side by side.\""), .direct("Did the defendant complete training?", "\"Yes, the use-of-force course four years earlier. {D.He} was a 22-year veteran.\""), .direct("Could the dark make this mistake easier?", "\"Yes. At 11 p.m. in a backyard, a dark grip on a dark hip is hard to tell by feel.\""), .direct("Was the Taser rig changed that week?", "\"Equipment was rotated. I cannot say exactly when {D.his} rig changed.\""), .cross("Did the defendant say anything after the shot?", "\"The body camera captured {DL} saying 'Oh no. Oh no.' It is clear {DL} did not mean to fire the pistol.\""), .cross("Does a mistake like this happen?", "\"It has happened elsewhere. It is rare, but it is documented.\""), .cross("Did the defendant warn the others?", "\"Yes. {DL} shouted 'Taser' to warn them.\""), .cross("Was {V} armed?", "\"No. {V} turned toward {DL} after climbing the fence, and {V} had nothing in {V.his} hands.\""), .cross("Did the defendant cooperate?", "\"Fully. {D.He} gave a statement and was devastated.\"")],
        defenseRole: "Human-factors expert",
        defenseExam: [.direct("What is your field?", "\"I am a human-factors expert. I study how people act under stress and how training affects motion.\""), .direct("How does this mistake happen?", "\"Under sudden stress, a trained motion can fire the wrong tool. The hand goes where practice sent it.\""), .direct("What is a weapon-confusion error?", "\"A person means to draw one tool and draws another. It is not intent. It is a failure of automatic motion.\""), .direct("Does darkness make it likelier?", "\"Yes. Low light removes visual checks, and the hand has only the grip to go on.\""), .direct("What role does carry position play?", "\"A large one. When both tools are on the same side, the hand can find the wrong one.\""), .direct("Does it excuse the carry setup?", "\"No. That is a separate question. The mistake was foreseeable, and the rule exists to prevent it.\""), .cross("Does this mean {D} was not at fault?", "\"I do not say that. I explain how it happens, and fault is for the jury.\""), .cross("Would a better holster have prevented this?", "\"Probably. A bright holster on the support side makes the mistake much less likely.\""), .cross("Did the defendant follow the carry rule?", "\"From the photos, not fully. The Taser sat on the same hip as the pistol.\""), .cross("Are you paid for your testimony?", "\"I am paid for my time, as in any case.\""), .cross("Did you speak with the defendant?", "\"No. I reviewed the records and the video.\"")],
        theory: ("{D} fired a gun and killed {V} by sloppy equipment handling.", "A tragic slip in the dark."),
        allocution: "\"I would trade places with that young person in a second.\"",
        truths: ("In training last spring {DL} scored lowest in the class on weapon-recognition drills and was told to practice.", "Armory logs showed {DL}'s training Taser had been out for repair for two months, so {DL} had drilled on a different model."),
        defendant: [.direct("What did you think you held?", "\"The Taser. I felt the grip I trained on, and I thought I was drawing the right tool.\""), .direct("Why did you yell Taser?", "\"To warn the others. I wanted everyone to know it was a Taser, so no one would panic.\""), .direct("Where was the Taser?", "\"On my left hip. The gun was on my right.\""), .direct("What happened when {V} turned?", "\"{V} climbed the fence and turned toward me. I drew and yelled Taser, and I fired.\""), .direct("What did you realize?", "\"The moment I heard the shot, I knew it was the pistol. I said, 'Oh no,' and ran to {V}.\""), .direct("What do you want {V}'s family to know?", "\"I am devastated. I never meant to hurt {V}, and I will live with this every day.\""), .cross("The Taser and pistol were on the same hip that night, weren't they?", "\"I thought they were on opposite sides. I was wrong.\""), .cross("The department requires them on opposite sides, doesn't it?", "\"Yes. I know the rule. I thought I was following it.\""), .cross("You fired a pistol at a 19-year-old, didn't you?", "\"Yes. I meant to use the Taser. I am so sorry.\""), .cross("{V} had nothing in {V.his} hands, did {V.he}?", "\"No. I did not see anything.\""), .cross("You are a 22-year veteran, aren't you?", "\"Yes. I trained for this, and I still made the mistake.\"")],
        openings: ("Deputies chased {V}, 19, through backyards at 11 p.m. after a report of a stolen scooter. {V} climbed a fence and turned toward {D}, a 22-year veteran, who yelled 'Taser!' and fired once with the pistol, killing {V} in the yard.", "It was a horrible mistake in the dark. {D} reached for a Taser and drew the pistol, then said 'Oh no' on the body camera, and the State must prove more than a tragedy."),
        closings: ("A Taser and a pistol on the same hip, a shout of 'Taser,' and a gunshot that killed a 19-year-old. {D} knew the rule and carried the setup that made this possible.", "A dark yard, a trained motion, and a mistake that {D} knew the instant it happened. The State must prove {D} acted recklessly, not that a tragedy occurred."),
        timeline: [(0, "10:55 p.m.: the stolen scooter call."), (0, "11:01 p.m.: the foot chase into a backyard."), (0, "11:03 p.m.: one shot fired; {VL} dies."), (2, "{DL} is placed on leave.")],
        identified: "Body camera.",
        mitigating: ["No prior criminal record", "The defendant has a long record of public service", "The defendant has expressed remorse"],
        mood: .divided,
        doctrines: ["burdenOfProof"],
        genders: ["D": .female, "V": .male])

    static let taxAgentGiftCardsV1 = SmallCases.make(
        key: "story.taxAgentGiftCards",
        category: .whiteCollar,
        headlines: ["Caller Posing as Deputy Said Seniors Missed Jury Duty, Took Kiosk Cash", "Crypto Kiosk Camera Shows Cash Fed Into Machine"],
        law: "extortion",
        threshold: 8,
        spec: "Threatened arrest of {V} and others to obtain payment of $21,000, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Callers posing as a sheriff's deputy told older residents on {DATE} that they had missed jury duty and faced arrest unless they paid by cash deposit at a crypto kiosk. Twelve victims paid $21,000. A kiosk camera showed {D} feeding stacks of bills into a machine. {DL} says {D.he} was paid to run errands and thought it was a debt-collection firm.",
        state: [E(.video, 3, "Kiosk Camera", "{D} deposits stacks of cash into a kiosk."), E(.digital, 3, "Spoofed Call Records", "Calls with a fake sheriff's number from a phone linked to {D}."), E(.statement, 2, "Victim", "'He said a deputy would come to my house.'")],
        defense: [E(.statement, 1, "Errand Runner", "{DL} says {D.he} was paid to deliver cash.")],
        role: "Victim",
        exam: [.direct("What were you told on the phone?", "\"That a deputy would arrest me for missing jury duty unless I paid by cash deposit at a crypto kiosk.\""), .direct("What did you do?", "\"I took $2,000 to a kiosk and sent it. I was terrified, and I followed every instruction.\""), .direct("Did you hear the caller's name?", "\"A name like a deputy's. It sounded official, and the number on my screen looked like the sheriff's office.\""), .direct("How did you feel?", "\"Frightened and ashamed. I had never missed jury duty, but the caller sounded so sure.\""), .direct("What happened after you sent the money?", "\"The caller told me to wait for a call. No call came, and I realized it was a scam.\""), .direct("What did you do then?", "\"I called the real sheriff's office, and a deputy told me the whole thing was fake.\""), .cross("Did you meet {D}?", "\"No. I never met {D}. I only know about {D.him} from what deputies told me.\""), .cross("Did the defendant call you?", "\"No. The calls came from a fake number. I never heard {D.his} voice that I know of.\""), .cross("How many people were victimized?", "\"Twelve, I am told, and $21,000 in all.\""), .cross("Did you see the kiosk camera?", "\"No. I only know it exists.\""), .cross("Did you get your money back?", "\"No. It is gone.\"")],
        defenseRole: "Kiosk store clerk",
        defenseExam: [.direct("What do you do at the store?", "\"I work the counter at a store with a crypto kiosk in the lobby. People feed cash into it all day.\""), .direct("Did {D} visit often?", "\"Almost every afternoon. {D} fed stacks of bills into the machine, and I assumed it was for a business.\""), .direct("Did the defendant seem nervous?", "\"Not really. {D.He} was calm and chatty, and sometimes bought a drink and talked about the weather with me.\""), .direct("Did you ask what the defendant was doing?", "\"Once. {D.He} said it was errands for an employer, and I let it go.\""), .direct("How much cash did the defendant deposit?", "\"Stacks of bills, thousands of dollars in a single visit. It was noticeable, though I did not count it.\""), .direct("Did you report it?", "\"No. I did not think of it as a crime then. I thought it was some kind of business for an employer.\""), .cross("Did you think it was strange?", "\"A little. People do not usually deposit that much cash that often, and I noticed the pattern after a few weeks.\""), .cross("Did the defendant ever show you a script or a phone?", "\"No. I only ever saw {D.him} at the kiosk, feeding in the bills, and never saw a script or a phone call.\""), .cross("Did {D} ever say who the employer was?", "\"No. I did not ask a name, and {D.he} did not offer one. I never asked who the employer was.\""), .cross("Would you have reported it if you knew?", "\"Yes. I would have called someone right away if I had known what the cash really was or where it came from.\""), .cross("Are you friendly with the defendant?", "\"We chatted at the counter now and then. I would not call us friends, only a clerk and a regular.\"")],
        theory: ("{D} helped scare seniors into paying.", "An errand runner for a debt-collection firm."),
        allocution: "\"I'm sorry for every person I hurt.\"",
        truths: ("{DL}'s phone held a script titled 'jury duty warrant.'", "{DL}'s chat with a contact saved as 'Boss' said the work was for a debt-collection firm."),
        defendant: [.direct("Did you make calls?", "\"No. I never made any call to any victim, and I never spoke to anyone about jury duty.\""), .direct("What did you do?", "\"I fed cash into the machine. I was paid to run errands, and I took cash to the kiosk and deposited it.\""), .direct("Who gave you the cash?", "\"A guy called Boss. I met Boss in a parking lot, and Boss gave me bags of cash.\""), .direct("What did you keep?", "\"Ten percent. It was my pay for the errands.\""), .direct("What did you think you were doing?", "\"Working for a debt-collection firm. Boss said people owed money and paid in cash, and I was moving it.\""), .direct("What do you want the victims to know?", "\"I am deeply sorry. I thought it was a legitimate job, and I did not know people were being frightened.\""), .cross("You deposited stacks of cash almost every afternoon, didn't you?", "\"Yes. I did, and I was paid for it.\""), .cross("The calls came from a phone linked to you, didn't they?", "\"So they say. I did not make them. I did not know.\""), .cross("You cannot produce Boss, can you?", "\"No. I have a chat and a phone number.\""), .cross("You kept ten percent of $21,000, didn't you?", "\"About that. I thought it was a normal commission.\""), .cross("You never asked where the cash came from, did you?", "\"I should have. I did not.\"")],
        openings: ("Callers posing as a sheriff's deputy told older residents they had missed jury duty and faced arrest unless they paid by cash deposit at a crypto kiosk. Twelve victims paid $21,000, and a kiosk camera showed {D} feeding stacks of bills into the machine.", "{D} was paid to run errands and thought the job was for a debt-collection firm. A courier who never made a call is not the voice that threatened anyone."),
        closings: ("A fake deputy, twelve victims, $21,000, and {D} at the kiosk almost every afternoon, keeping ten percent. {D} was paid to launder their fear.", "An errand job, a boss no one can find, and no call from {D}'s mouth. The State must prove {D} knew the cash came from a scam."),
        timeline: [(0, "Week 1: the calls begin."), (0, "Week 2: cash is deposited at the kiosk."), (0, "Week 3: complaints reach the sheriff."), (6, "{DL} is arrested at the kiosk.")],
        identified: "Kiosk camera footage.",
        aggravating: ["The victim was particularly vulnerable", "The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "I thought a deputy was coming for me.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let wetlandsFillDumpV1 = SmallCases.make(
        key: "story.wetlandsFillDump",
        category: .property,
        headlines: ["Excavator Cuts Ditch Through Protected Marsh on Farm", "Drone Footage Shows Marsh Drained Overnight"],
        law: "injuryRealProperty",
        threshold: 7,
        spec: "Willfully and wantonly injured real property of {V}, the State, causing damage of $52,000, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A drainage ditch half a mile long was cut through a protected marsh on {DATE}, draining it into a creek. A state drone showed excavator tracks leading to the farm where {D} works as an excavation contractor. {DL} says the landowner said it was dry farmland.",
        state: [E(.video, 3, "Drone Footage", "A fresh ditch and excavator tracks into the marsh."), E(.document, 3, "Permit Denial Letter", "The state denied a drainage permit for the parcel the year before."), E(.statement, 2, "State Inspector", "'The marsh is mapped on every state layer.'")],
        defense: [E(.statement, 1, "Landowner's Word", "{DL} says the landowner called it dry land.")],
        role: "State inspector",
        exam: [.direct("What did you find at the marsh?", "\"A fresh ditch half a mile long and a drained marsh. The ditch cut through the marsh and sent its water into a creek.\""), .direct("Was the area protected?", "\"Yes. It is mapped and posted in state records. As I said, the marsh is mapped on every state layer.\""), .direct("What did the drone footage show?", "\"A fresh ditch and excavator tracks leading into the marsh, and the tracks lead to the farm where {D} works.\""), .direct("Were there signs on site?", "\"No. There were no posted signs at the marsh itself.\""), .direct("Did {D} own the land?", "\"No, the farmer did. {D.He} works as an excavation contractor and dug the ditch.\""), .direct("What did the permit letter say?", "\"The state denied a drainage permit for the parcel the year before. It is in the file.\""), .cross("Did the landowner tell the defendant it was dry farmland?", "\"That is what {D.he} says. I do not know what the landowner said.\""), .cross("Did the defendant know the permit was denied?", "\"I cannot say. The denial went to the landowner.\""), .cross("Is the marsh visible from the road?", "\"Not clearly. Looking at it, a person might think it was a wet field.\""), .cross("Did the defendant cooperate?", "\"Yes. {D.He} said the landowner ordered the work and showed us the excavator.\""), .cross("Did the ditch actually drain the marsh?", "\"Yes. The water level fell, and the creek rose for a time.\"")],
        defenseRole: "Landowner",
        defenseExam: [.direct("What is your relationship to this land?", "\"I own the land. {D} dug a ditch for me, at my instruction.\""), .direct("What did you tell {D}?", "\"That it was a wet field, not a marsh. I said I wanted it drained for farming.\""), .direct("Did you get a permit?", "\"The permit was denied. I knew that, and I ordered the work anyway.\""), .direct("Did you tell the defendant about the denial?", "\"I do not think I did. I did not want to complicate things.\""), .direct("Why did you want it drained?", "\"The field was too wet to plant. I thought a ditch would fix it.\""), .direct("How did you pay the defendant?", "\"By the day, in cash. {D.He} was a contractor, and I paid what we agreed on at the end of each day.\""), .cross("Did you know the marsh was protected?", "\"I knew it was mapped. I told myself it was a wet field.\""), .cross("Did the defendant ask for a permit?", "\"No. {D.He} did not ask for a permit, and I did not offer one. I let the whole question slide.\""), .cross("Did you check a map with the defendant?", "\"No. We never looked at a map together, and I never showed {DF} the state layers or the denial letter.\""), .cross("Are you taking responsibility?", "\"I am. The permit was mine to get, and the choice to dig anyway was mine, and I will answer for it.\""), .cross("Do you want {D} blamed?", "\"No. {D.He} followed my orders and my markings. If anyone should be blamed for the marsh, it is me.\"")],
        theory: ("{D} drained a protected marsh.", "A contractor following the landowner."),
        allocution: "\"I should have checked the maps.\"",
        truths: ("{DL} signed for a certified stop-work letter and kept digging two more days.", "The landowner's survey marked upland stakes, and {DL}'s excavator log stopped the day the notice was delivered."),
        defendant: [.direct("Did you dig the ditch?", "\"Yes, on the landowner's order. I ran the excavator for several days and followed the landowner's markings.\""), .direct("Did you think it was marsh?", "\"I thought it was a wet field. It looked like soggy farmland, and the landowner called it that.\""), .direct("Did you check a map?", "\"No, I should have, and I regret that. I took the landowner at their word and never pulled up a state map.\""), .direct("What did the landowner tell you?", "\"That it was dry farmland that held water after rain. The landowner said a ditch would help.\""), .direct("Did you know about the permit?", "\"No. No one told me a permit had ever been denied for that parcel, and the landowner never mentioned a letter.\""), .direct("What do you want the state to know?", "\"I am deeply sorry. I did not know it was a protected marsh, and I will help repair what I can.\""), .cross("You dug a ditch half a mile long through a marsh, didn't you?", "\"Yes, I dug it, and I did not see it as a marsh. To me it was a soggy field that held water.\""), .cross("You are an excavation contractor, aren't you?", "\"Yes, and I should have checked more carefully before I ever started the machine. That is on me, as a professional.\""), .cross("A state map shows the marsh, doesn't it?", "\"So the inspector says. I did not look at any map, and I did not walk the area first to check.\""), .cross("You did not ask for a permit, did you?", "\"No. I assumed the landowner had arranged everything with the state before hiring me, and I did not ask to see a permit.\""), .cross("The marsh drained into a creek because of your ditch, didn't it?", "\"Yes, it drained into the creek, and I did not intend that. I wish I had understood what I was cutting.\"")],
        openings: ("A drainage ditch half a mile long was cut through a protected marsh, draining it into a creek. A state drone showed excavator tracks leading to the farm where {D} works as an excavation contractor, and the state had denied a drainage permit for the parcel the year before.", "The landowner told {D} it was dry farmland, and {D} followed instructions. An excavator operator who never saw a map or a permit is not a polluter."),
        closings: ("A fresh ditch half a mile long, excavator tracks to {D}'s farm, a mapped marsh, and a denied permit. {D} dug where the state said not to dig.", "A landowner who ordered the ditch, a field that looked wet, and a contractor who trusted the owner. The State must prove {D} knew the marsh was protected."),
        timeline: [(-365, "The state denies the drainage permit."), (0, "Week 1: the ditch is cut."), (0, "Week 2: the state drone flies the site."), (9, "A stop-work letter is delivered.")],
        identified: "State drone footage.",
        mood: .divided,
        doctrines: ["mistakeOfFact"])

    static let courthouseHallFightV1 = SmallCases.make(
        key: "story.courthouseHallFight",
        category: .publicOrder,
        headlines: ["Cousins Trade Punches at Courthouse Metal Detector After Custody Hearing", "Deputies Pull Two Families Apart in Lobby"],
        law: "disorderly",
        threshold: 6,
        spec: "Disturbed the peace of the court by fighting, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "Two families fought in a courthouse lobby near the metal detector on {DATE}, minutes after a custody hearing. A security camera caught {D} throwing a punch. {DL} says another relative hit {D.him} with a lanyard first.",
        state: [E(.video, 3, "Lobby Camera", "{D} punches a man in the line."), E(.statement, 2, "Deputy", "The deputy saw the swing and heard shouting."), E(.forensic, 2, "Medical Note", "A swollen cheek on the other man.")],
        defense: [E(.statement, 1, "Struck First", "{DL} says someone struck {D.him} with a lanyard first.")],
        role: "Courthouse deputy",
        exam: [.direct("What happened in the lobby that day?", "\"Two groups started yelling at the metal detector, minutes after a custody hearing, and it turned into a fight.\""), .direct("What did you see {D} do?", "\"Throw a punch. The lobby camera shows {D} swinging at another person in the line.\""), .direct("How many people were involved?", "\"Six or seven, from two families. People were shoving, shouting, and pulling at one another near the detector.\""), .direct("What did you hear?", "\"Raised voices and shouting. I heard names and insults, and then a scuffle broke out.\""), .direct("What was the injury?", "\"A swollen cheek on the person who was hit. The medical note records the swelling and nothing more serious.\""), .direct("How did the fight end?", "\"Deputies stepped in, separated the families, and cleared the lobby. It took about two minutes.\""), .cross("Did anyone hit the defendant first?", "\"I saw an arm swing. I could not see who swung it or what it landed on.\""), .cross("Did you see a lanyard?", "\"I saw something swinging near {D.his} head. I cannot say what it was.\""), .cross("Did the defendant keep fighting?", "\"No. {D.He} stopped when I got between the groups and did not resist.\""), .cross("Was the situation tense before the punch?", "\"Very. Everyone was upset about the hearing, and the line was packed.\""), .cross("Did the defendant cooperate with deputies?", "\"Yes. {D.He} was escorted out and gave a statement without complaint.\"")],
        defenseRole: "Court clerk",
        defenseExam: [.direct("Where do you work?", "\"I am a clerk in the courthouse. I was walking through the lobby when the fight started.\""), .direct("Did you see a swing before the punch?", "\"I saw a lanyard swing. It whipped around and caught {D} near the head, as I recall.\""), .direct("Who swung it?", "\"I could not tell. Several people were close together, and the lanyard was in the middle of it.\""), .direct("What did {D} do next?", "\"Turned and punched. It was quick, and I think it was a reaction.\""), .direct("How did the defendant act earlier in the lobby?", "\"Quiet. {D.He} stood off to the side during the hearing and spoke softly with a family member.\""), .direct("How loud was the lobby?", "\"Very. The detector beeps, people were shouting, and deputies were calling out.\""), .cross("Did you see the punch land?", "\"Yes. I saw it connect with the other person's cheek.\""), .cross("Did you see the defendant start the shoving?", "\"No. I did not see how it started.\""), .cross("Are you certain about the lanyard?", "\"Fairly. I saw it clearly for a moment, and then it was gone.\""), .cross("Did you know either family?", "\"No. I know them only as people in the courthouse.\""), .cross("Would you say the defendant was provoked?", "\"I would say something struck {DF} before the punch. I cannot say more.\"")],
        theory: ("{D} threw a punch in a courthouse lobby.", "A reaction to being struck first."),
        allocution: "\"I'm sorry. It was the wrong place.\"",
        truths: ("{DL} had texted a relative before the hearing, 'if they say it, I'll shut it.'", "The other relative struck {DL} on the back of the head before the punch."),
        defendant: [.direct("Did you punch?", "\"Yes, after being hit. I was struck, I turned, and I swung without thinking.\""), .direct("Who hit you?", "\"A relative of the other side. I did not see the person's face, but I felt the lanyard hit my head.\""), .direct("You texted before the hearing, didn't you?", "\"I was angry. I did not plan a fight, and I did not mean it that way.\""), .direct("Could you have walked away?", "\"It all happened fast. I did not have time to think about walking away.\""), .direct("What was the hearing about?", "\"Custody. It was a painful hearing, and everyone was on edge.\""), .direct("What do you want the court to know?", "\"I am sorry that it happened in a courthouse. I should have kept my temper, even after being struck.\""), .cross("The camera shows you throwing a punch, doesn't it?", "\"Yes. I did, and I am not proud of it.\""), .cross("The other person had a swollen cheek, didn't they?", "\"So I understand. I am sorry for that.\""), .cross("You were angry before the hearing, weren't you?", "\"Yes. I was worried about my family and upset about what might be said.\""), .cross("You could have told a deputy, couldn't you?", "\"I could have. I reacted instead.\""), .cross("Nobody saw who hit you first, did they?", "\"A clerk saw the lanyard. That is enough for me.\"")],
        openings: ("Two families fought in a courthouse lobby near the metal detector, minutes after a custody hearing. A security camera caught {D} throwing a punch that left a swollen cheek on another person.", "Someone struck {D} with a lanyard first, and {D} swung back in a reflex. A fight that began with a blow to {D} is not an unprovoked assault."),
        closings: ("A camera shows {D} throwing the punch, a deputy saw the swing, and another person had a swollen cheek. {D} chose to swing in a courthouse.", "A lanyard to the head, a lobby in chaos, and a reaction in a heartbeat. The State must prove {D} was the aggressor, not that {D} swung back."),
        timeline: [(0, "10 a.m.: the custody hearing ends."), (0, "10:20 a.m.: both families reach the metal detector."), (0, "10:22 a.m.: the fight."), (0, "11 a.m.: {DL} is cited.")],
        identified: "A lobby camera.",
        mood: .sympathetic,
        doctrines: ["selfDefense"])

    static let checkpointDwiV1 = SmallCases.make(
        key: "story.checkpointDwi",
        category: .traffic,
        headlines: ["Broken Tail Light Stop Ends in DWI Arrest", "Deputy's Body Camera Records Field Sobriety Tests"],
        law: "dwi",
        spec: "Operated a motor vehicle on a street while subject to an impairing substance, on {DATE}.",
        ages: 21...60,
        victim: false,
        summary: "A deputy stopped {D} at 1 a.m. on {DATE} for a broken tail light and noted the smell of alcohol. {D} failed several field sobriety tests and blew 0.09 at the jail. {DL} says the machine was affected by mouthwash and acid reflux.",
        state: [E(.forensic, 3, "Breath Test", "0.09 on the jail instrument."), E(.video, 2, "Body Camera", "{D} sways and misses a heel-to-toe step.")],
        defense: [E(.statement, 1, "Reflux", "{DL} says reflux and mouthwash raised the reading.")],
        role: "Sheriff's deputy",
        exam: [.direct("Why did you stop {D}?", "\"A broken tail light at 1 a.m. It was a routine stop, and I pulled in behind the car and turned on my lights.\""), .direct("What did you notice at the window?", "\"A smell of alcohol. I also saw that {D}'s speech was a little slow and eyes were red.\""), .direct("What did you see during the field tests?", "\"{D.He} swayed and missed a heel-to-toe step. The body camera records it.\""), .direct("What was the breath reading?", "\"0.09 on the jail instrument, which is over the legal limit of 0.08.\""), .direct("Did the defendant say anything about medical conditions?", "\"{D.He} said acid reflux. {D.He} also said {D.he} had rinsed with mouthwash after dinner.\""), .direct("How did the defendant behave?", "\"Polite and cooperative. {D.He} followed instructions and did not argue.\""), .cross("Did the defendant have reflux?", "\"{D.He} said so. I did not verify it, and I did not see a diagnosis.\""), .cross("Can mouthwash affect a breath test?", "\"It can, if the test is taken soon after rinsing. That is why we observe the subject first.\""), .cross("Did you observe the defendant before the test?", "\"Yes. I observed {D.him} at the jail before the breath test, as the procedure requires.\""), .cross("Was it cold and late?", "\"Yes. It was 1 a.m. and cold, and many people sway more in those conditions.\""), .cross("Was the reading close to the limit?", "\"Yes. 0.09 is close to 0.08. I do not say it is far over.\"")],
        theory: ("{D} drove after drinking.", "A mouth-alcohol reading."),
        allocution: "\"I should have called a ride.\"",
        truths: ("A restaurant receipt showed four drinks on {DL}'s bar tab that night.", "Body camera timestamps show the deputy observed {DL} for only eight minutes, not the required fifteen."),
        defendant: [.direct("How much did you drink?", "\"Two beers. I had them with dinner over a couple of hours, and I felt fine to drive home.\""), .direct("Why the mouthwash?", "\"I always rinse after dinner. It is a habit, and I did it before I got in the car.\""), .direct("What about the acid reflux?", "\"I have reflux, and it flares up after eating. It can send acid into my mouth, and I worried about my breath.\""), .direct("You swayed on camera, didn't you?", "\"It was cold and late. I was tired, and the ground was uneven, and I did my best.\""), .direct("How did you feel during the stop?", "\"Nervous. I had never been stopped for alcohol, and I wanted to cooperate.\""), .direct("What do you want the court to know?", "\"I did not think I was over the limit. I believe the machine was affected by the mouthwash and reflux.\""), .cross("You blew 0.09, didn't you?", "\"So the jail says. I do not think it was accurate.\""), .cross("You smelled of alcohol, didn't you?", "\"I had two beers at dinner. That is what the deputy smelled.\""), .cross("You missed a heel-to-toe step, didn't you?", "\"Yes. It was cold and dark, and I was nervous.\""), .cross("You rinsed with mouthwash that night, didn't you?", "\"Yes. It was after dinner, before I left the restaurant.\""), .cross("You chose to drive after drinking, didn't you?", "\"Two beers, hours before. I thought I was fine.\"")],
        openings: ("A deputy stopped {D} at 1 a.m. for a broken tail light and noted the smell of alcohol. {D} failed several field sobriety tests and blew 0.09 at the jail.", "{D} had two beers with dinner, rinsed with mouthwash, and has acid reflux that can skew a breath test. A reading barely over the limit is not proof of impairment."),
        closings: ("A broken tail light, a smell of alcohol, missed steps on camera, and a 0.09 at the jail. {D} was over the legal limit behind the wheel.", "Two beers, mouthwash, reflux, and a breath machine that reads high under those conditions. The State must prove {D} was impaired and not simply tired and cold."),
        timeline: [(0, "8 p.m.: dinner and drinks."), (0, "1 a.m.: the stop for the tail light."), (0, "1:50 a.m.: the breath test at the jail.")],
        identified: "A traffic stop for a broken tail light.",
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["V": .male])

    static let joggerChaseV1 = SmallCases.make(
        key: "story.joggerChase",
        category: .violent,
        headlines: ["Neighborhood Watch Leader Shoots Delivery Worker After Quad Chase", "Doorbell Video Shows Package Pickup Before Chase"],
        law: "murder2",
        threshold: 9,
        spec: "Unlawfully and with malice killed {V} with a rifle after pursuing {V.him} on an all-terrain vehicle.",
        ages: 55...68,
        victim: true,
        summary: "On {DATE}, {V}, 24, a delivery worker, took a package from a porch to carry it to the correct house next door. A doorbell camera recorded {V.him}, and {D}, a retired corrections officer who ran the neighborhood watch, saw the clip. {D} and a fellow watch member took a rifle and an ATV, caught up with {V} on a dirt path, and cornered {V.him} at a ditch. A neighbor's phone recorded a struggle and three shots. {V} died on the path. {DL} says {D.he} believed {V} was a thief and that {V} lunged for the rifle.",
        state: [E(.video, 3, "Doorbell Clip", "{V} picks up a package and walks next door."), E(.video, 3, "Neighbor's Phone Video", "{V} backs against a ditch, a struggle follows, and three shots."), E(.digital, 2, "Watch Group Texts", "{DL} writes, 'we'll teach this one a lesson.'"), E(.statement, 2, "911 Call", "{DL} says 'I shot the thief' before giving an address.")],
        defense: [E(.document, 2, "Package Thefts", "Eleven porch thefts reported in the neighborhood in two months."), E(.forensic, 2, "Forearm Scratches", "Photos of scratches on {DL}'s forearm."), E(.document, 1, "Watch Training", "{DL} completed a neighborhood watch course.")],
        role: "Neighbor who filmed",
        exam: [.direct("What did you record?", "\"The ATV, a person backing up against a ditch, a struggle over a rifle, and three shots.\""), .direct("What did you see before the shots?", "\"Two people on an ATV with a rifle rode down a dirt path after someone on foot. They cornered the person at the ditch.\""), .direct("Did {V} have a weapon?", "\"I did not see one. {V} had nothing in hand that I could see.\""), .direct("Did {V} grab the rifle?", "\"Their hands were on it. There was a tug-of-war, and I cannot tell who held it first.\""), .direct("What happened at the end?", "\"Three shots, and {V} fell. I called 911 as soon as I stopped filming.\""), .direct("What did you hear?", "\"Shouting and the engine. I heard someone yell 'drop it,' and then the shots.\""), .cross("Who started the struggle?", "\"The video starts after it began. I did not see how the confrontation began.\""), .cross("Could you see {V}'s face?", "\"Not clearly. I saw a person backing against the ditch, scared and trapped.\""), .cross("Did {V} lunge at the rifle?", "\"I cannot say. Their hands were on it, and it was too fast.\""), .cross("Were the watchers wearing anything?", "\"Camouflage jackets and one had a radio. I did not see badges.\""), .cross("Did you know {D}?", "\"I knew {D} as the head of the neighborhood watch. {DL} had been a corrections officer.\"")],
        defenseRole: "Watch group member",
        defenseExam: [.direct("What is your role?", "\"I am a member of the neighborhood watch. I was there that morning and saw everything.\""), .direct("What did you see?", "\"{V} lunged for the rifle. I saw hands on the barrel, and {D} struggled to keep control.\""), .direct("Could you hear what was said?", "\"Not clearly. There was shouting, and the ATV engine was loud.\""), .direct("Why did the watch chase {V}?", "\"We saw the video of a person taking a package. There had been thefts on our street.\""), .direct("Did {D} plan to hurt anyone?", "\"No. {DF} said we would talk to the person and call the sheriff.\""), .direct("What happened after the shots?", "\"{D.He} called 911 and said what happened. I knelt by {V} and tried to help.\""), .cross("Why did you bring a rifle?", "\"For protection. {D.He} said to bring it, and I did not question it.\""), .cross("Did you see {V} with a weapon?", "\"No. I did not see a weapon.\""), .cross("Did you read the watch texts?", "\"Yes. One said 'we'll teach this one a lesson.' I did not like it.\""), .cross("Did anyone tell {V} to stop?", "\"We shouted. I do not know what {V} heard.\""), .cross("Are you friends with the defendant?", "\"We are neighbors and watch members. I would say the same of any neighbor.\"")],
        theory: ("{D} hunted down a delivery worker and shot {V.him}.", "A frightened citizen defending against a lunge at {D.his} rifle."),
        allocution: "\"I thought I was protecting my street. I was wrong.\"",
