        state: [E(.digital, 3, "Loyalty Card Data", "Shower credits on {D}'s account at both stops within hours of the last sightings."), E(.forensic, 3, "Tarp Fibers", "Fibers from both tarps match a roll in {D}'s trailer."), E(.video, 2, "Fuel Lot Camera", "{D}'s rig parks near the rest area the night {V} disappears."), E(.document, 2, "Prior Assault Record", "A prior conviction for assault on a female.")],
        defense: [E(.document, 2, "Common Tarp", "The same tarp is sold at hundreds of stores."), E(.forensic, 2, "No DNA in Cab", "No DNA from either woman in {DL}'s cab."), E(.document, 1, "Stop Traffic", "Thousands of drivers shower at those stops weekly.")],
        role: "Truck stop cashier",
        exam: [.direct("Tell us about your job as a truck stop cashier.", "\"I work the register at a truck stop. I ring up fuel, food, and showers, and I see hundreds of drivers each week.\""), .direct("What happened to {V}?", "\"{V}, who was 26, accepted a ride from a truck stop and was found strangled in a drainage culvert beside an interstate rest area on I-85.\""), .direct("What did you see the night {V} was last seen?", "\"{V} came in and talked with a few people. I remember because it was a busy night, and I told deputies what I saw.\""), .direct("What does the loyalty card data show?", "\"Shower credits on {D}'s account at both stops within hours of the last sightings. {D.He} was there both evenings.\""), .direct("What did the fuel lot camera show?", "\"{D.his} rig parked near the rest area the night {V} disappeared.\""), .direct("What was found in {D}'s trailer?", "\"A roll of blue tarp. Fibers from both tarps match that roll.\""), .cross("Is the tarp common?", "\"Yes. The same tarp is sold at hundreds of stores. Many drivers carry it.\""), .cross("How many drivers use those stops?", "\"Thousands each week. A shower credit puts {DL} at the stop, but it does not put {DL} with {V}.\""), .cross("Was DNA found in the defendant's cab?", "\"No. No DNA from either person was found in the cab. That could mean nothing was there, or it could be cleaned.\""), .cross("Did another driver's card appear at both stops?", "\"Yes. A second driver's card was swiped at both stops that evening. That driver was later arrested with a victim's phone.\""), .cross("Does the defendant have a prior record?", "\"A prior assault conviction. I do not know the details, and I cannot say how it relates to this case.\"")],
        defenseRole: "Fellow trucker",
        defenseExam: [.direct("Explain to the jury how you know {D}.", "\"I am a fellow trucker. We have crossed paths at truck stops for years. I know {D} as a quiet, careful driver.\""), .direct("What do you know about those truck stops?", "\"They are busy. Thousands of drivers shower there every week. Many use loyalty cards, and many share cards.\""), .direct("What do you know about tarps?", "\"Truckers use blue tarps constantly. We buy them at truck stops and hardware stores. They are not unusual.\""), .direct("What did you see of the defendant on those nights?", "\"I saw {DF}'s rig parked at a stop, as usual. I did not see {DF} with anyone, and I did not see anything wrong.\""), .direct("What kind of person is the defendant?", "\"Polite and private. {DF} keeps to {DF}'s self. I never saw {DF} harass anyone, and I was surprised by the charges.\""), .direct("Do drivers share loyalty cards?", "\"Sometimes. A card can be used by friends or coworkers. A swipe does not always mean the owner was there.\""), .cross("Did you see the defendant on both nights?", "\"No. I saw {D.him} once. I cannot say where {D.he} was on the other night.\""), .cross("Did you see {V} at the truck stop?", "\"No. I did not know {V}. I only learned about {V} afterward.\""), .cross("Do you know about the defendant's prior conviction?", "\"Yes. I heard about it. It was long ago, and I have not seen anything to suggest it is relevant.\""), .cross("Did you see {D}'s trailer?", "\"I have seen it. I did not look at the tarps, and I cannot say what else was in it.\""), .cross("Did the defendant ever talk about riders?", "\"No. {D.He} never mentioned giving rides. I do not know whether {D.he} did.\"")],
        theory: ("{D} picked up and killed women at rest areas.", "A common route and a common tarp."),
        allocution: "\"I do not have anything to say.\"",
        truths: ("{DL}'s tablet held photos of both women's shoes taken in the sleeper berth.", "A second driver's loyalty card was swiped at both stops that evening, and he was later arrested with a victim's phone."),
        defendant: [.direct("Tell us about your work as a trucker.", "\"I drive long hauls and sleep in my truck. I stop at truck stops for showers and fuel, like thousands of other drivers.\""), .direct("Were you at both stops?", "\"Yes. I use those stops on my route, and my loyalty card shows my showers. That does not mean I met anyone.\""), .direct("Did you harm {V}?", "\"No. I did not. I never met {V}, and I never harmed anyone. I was shocked when deputies came.\""), .direct("Why was a roll of blue tarp in your trailer?", "\"I use tarps to cover loads. They are sold everywhere, and I buy them at any store that carries them.\""), .direct("What about the photos on your tablet?", "\"They are photos of shoes taken in the sleeper berth. I do not know why they are there, and I did not take them to harm anyone.\""), .direct("How do you feel about being accused?", "\"The word for it is scared and angry. I have a prior record, and I know that makes me easy to blame. I did not do this.\""), .cross("Your rig was parked near the rest area the night {V} disappeared, wasn't it?", "\"Yes. I park near many rest areas. I did not see {V}.\""), .cross("You have a prior assault conviction, don't you?", "\"Yes. I was convicted long ago. I have not hurt anyone since.\""), .cross("Tarp fibers match the roll in your trailer, don't they?", "\"So the lab reports. The same roll is in thousands of trailers.\""), .cross("Photos of two people's shoes were on your tablet, weren't they?", "\"Yes. I cannot explain it. I did not take them to hurt anyone.\""), .cross("Your shower credits match the evenings, don't they?", "\"Yes. I showered those nights. So did thousands of others.\"")],
        openings: ("Eight months apart, two people who had accepted rides from truck stops were found strangled in drainage culverts beside interstate rest areas, wrapped in blue tarps. A loyalty account in {D}'s name shows showers at both stops the evenings each was last seen, and tarp fibers match a roll in {D}'s trailer.", "The defense will present thousands of drivers at those stops, tarps sold at hundreds of stores, no DNA in the cab, and another driver whose card was swiped at both stops and who was arrested with a victim's phone."),
        closings: ("Showers at both stops within hours of the last sightings, a rig near the rest area, tarp fibers that match, photos of two people's shoes, and a prior assault conviction. {V} was found in a culvert.", "Thousands of drivers, a common tarp, no DNA in the cab, and a second driver arrested with a victim's phone. The State has not proved that {D} harmed anyone."),
        timeline: [(-240, "A woman disappears from a stop on I-77 and is found two days later."), (0, "{VL} is last seen at an I-85 truck stop."), (2, "{VL} is found in a culvert."), (60, "Loyalty account data requested for both stops."), (66, "{DL}'s rig is searched; the tarp roll is seized.")],
        identified: "Cross-matching loyalty card data from both truck stops.",
