        state: [E(.video, 3, "Register Camera", "{D} checks out with four laptops."), E(.digital, 3, "Loyalty Account Records", "The loyalty number is {D}'s."), E(.physical, 2, "Cloned Cards", "Three blank cards with magnetic stripes in {D}'s car.", .search)],
        defense: [E(.statement, 1, "Friend's Order", "{DL} says {D.he} picked up a friend's order.")],
        role: "Store security manager",
