        defenseRole: "Friend",
        defenseExam: [.direct("Tell the jury how you know {D}.", "\"I am a friend of {D}'s. We have known each other for years, and I asked {D.him} to help me pick up an online order.\""), .direct("What did you ask the defendant to do?", "\"To pick up a pre-paid online order at the store. I was busy and could not go myself.\""), .direct("What did you tell the defendant about the order?", "\"That it was already paid. I said it was ready for pickup, and I told {D.him} to use the loyalty number.\""), .direct("Did you give the defendant any cards?", "\"I do not want to answer that without a lawyer. I only told {D.him} to pick up an order.\""), .direct("What kind of person is the defendant?", "\"Helpful and trusting. {D.He} does favors without asking questions. I took advantage of that, and I feel terrible.\""), .direct("How do you feel about what happened?", "\"Mostly I feel awful. {D.He} is in court because of me. I should have told the truth earlier.\""), .cross("Did you use cloned cards?", "\"I decline to answer that. I only asked {D.him} to pick up an order.\""), .cross("Was the order really pre-paid?", "\"I do not want to say. I asked {D.him} to pick it up, and I did not explain more.\""), .cross("Did you tell {D} to resell laptops?", "\"No. I did not. I only asked {D.him} to pick up the order.\""), .cross("Did you know about the cloned cards?", "\"I decline to answer. I do not want to incriminate myself.\""), .cross("Did the defendant know?", "\"I do not think so. {DF} trusted me, and I did not tell {DF} the full story.\"")],
        theory: ("{D} bought laptops with cloned cards.", "A favor for a friend."),
        allocution: "\"I knew something was off.\"",
        truths: ("{DL} resold three of the laptops online the next day.", "Messages show a friend asking {DL} to pick up a pre-paid online order."),
        defendant: [.direct("Describe what you were doing at the store.", "\"I was picking up an order for a friend. The friend told me it was pre-paid online, and I just needed to collect it.\""), .direct("Did you know the cards were cloned?", "\"No. I did not. I thought they were the friend's cards. I did not look closely.\""), .direct("Why did you resell three laptops?", "\"I thought they were mine to sell. The friend gave them to me as payment, and I sold them. I should have asked.\""), .direct("Why were cloned cards in your car?", "\"The friend left them there. I did not look at them. I did not know what they were.\""), .direct("What did you tell deputies?", "\"I told them about the friend and showed the messages. I did not hide anything.\""), .direct("How has this affected you?", "\"I am used. I trusted a friend and ended up in court. I will never help anyone pick up an order again.\""), .cross("You checked out with four laptops, didn't you?", "\"Yes. I did. I thought I was following instructions.\""), .cross("Three cloned cards were in your car, weren't they?", "\"Yes. They were. I know how it looks, and I did not know what they were.\""), .cross("You resold three of the laptops, didn't you?", "\"Yes. I did. I thought they were mine to sell, and I know that was wrong.\""), .cross("Your loyalty number was used at checkout, wasn't it?", "\"Yes. It was mine. I used it as I usually do.\""), .cross("You cannot prove the friend's order was pre-paid, can you?", "\"I have messages that say so. I know they are not receipts.\"")],
        openings: ("On {DATE}, a group used cloned credit cards to buy eleven laptops at a big retail store. A loyalty phone number used at checkout belonged to {D}, and deputies found three cloned cards in {D}'s car.", "The defense will present a friend who asked {D} to pick up a pre-paid order, messages that show the request, and a person who trusted a friend. {D} did not know the cards were cloned."),
        closings: ("Eleven laptops bought with cloned cards, {D} at the register with four of them, three cloned cards in {D}'s car, and three laptops resold the next day. The loyalty number is {D}'s.", "A favor for a friend, a pre-paid order, and messages that show the request. The State has not proved that {D} knew the cards were cloned."),
        timeline: [(0, "Afternoon: eleven laptops are bought."), (0, "5 p.m.: the retailer flags the cards."), (1, "{DL}'s loyalty number is traced."), (5, "The car is searched.")],
