        summary: "{V} waited in a drive-through lane on {DATE} when a delivery van cut the corner, scraped the driver's side of {V.his} car and drove away. {V} photographed the van. A company dispatch log shows {D} drove it. {DL} says {D.he} felt a gust and a bump but thought it was a loose mirror hitting a curb.",
        state: [E(.video, 3, "Drive-Through Camera", "A white van scrapes a car in the lane and leaves."), E(.document, 2, "Dispatch Records", "{D} was assigned that van at that hour.")],
        defense: [E(.statement, 1, "Loose Mirror", "{DL} says a loose mirror bumped a curb.")],
        role: "Sheriff's deputy",
        exam: [.direct("Please explain your role as a sheriff's deputy.", "\"I respond to crashes, including hit-and-runs. I review camera video, interview witnesses, and trace vehicles to their drivers.\""), .direct("What happened to {V} on {DATE}?", "\"{V} was waiting in a drive-through lane when a delivery van cut the corner, scraped the driver's side of {V}'s car, and drove away.\""), .direct("What did the camera show?", "\"A white van scraping a car in the lane and leaving. {V} also photographed the van.\""), .direct("How did you identify the driver?", "\"A company dispatch log shows {D} was assigned that van at that hour. We spoke with {D.him}.\""), .direct("What did {D} say?", "\"{D.He} said {D.he} felt a gust and a bump but thought it was a loose mirror hitting a curb.\""), .direct("What did the defendant ask the dispatcher?", "\"{DL} called the dispatcher and asked, Did anyone see that? That is a notable question.\""), .cross("Was the mirror loose?", "\"A mechanic confirmed the mirror had been loose for weeks and could rattle like a hit. That supports {D.his} account.\""), .cross("Was anyone hurt?", "\"No. {V} was not hurt. The damage was to the car's driver's side.\""), .cross("Did the defendant stop?", "\"No. {D.He} did not stop. {D.He} said {D.he} did not know it had hit anything.\""), .cross("Did the defendant cooperate?", "\"Yes. {D.He} gave a statement and showed the van. {D.He} did not hide anything.\""), .cross("Could a loose mirror sound like a hit?", "\"Yes, according to the mechanic. I cannot say it did, and I do not know what {D.he} heard.\"")],
        theory: ("{D} sideswiped an occupied car and left.", "A driver who thought it was a loose mirror."),
        allocution: "\"I should have stopped to check.\"",
        truths: ("{DL} called the dispatcher and asked, 'Did anyone see that?'", "A mechanic confirmed the van's mirror had been loose for weeks and could rattle like a hit."),
        defendant: [.direct("What can you tell us about your job as a delivery driver?", "\"I drive a delivery van on a tight schedule. I make many stops each day, and I take care in the lanes and lots.\""), .direct("What did you feel on {DATE}?", "\"A gust and a bump. I thought it was the loose mirror hitting a curb. The mirror had been loose for weeks.\""), .direct("Did you know you hit a car?", "\"No. I did not. I did not see a car in the mirror, and I kept going.\""), .direct("Why did you call the dispatcher?", "\"I wanted to ask if anyone saw the bump. I wanted to check that nothing happened. I was not trying to hide anything.\""), .direct("What did you do when deputies spoke to you?", "\"I told them everything and showed the mirror. I said I had felt a bump and thought it was the mirror.\""), .direct("Looking back, how do you feel about it?", "\"I feel sorry. If I hit {V}'s car, I wish I had stopped. I did not know.\""), .cross("You cut the corner, didn't you?", "\"Yes. I may have. I was in a hurry. I did not see {V}'s car.\""), .cross("You asked the dispatcher whether anyone saw that, didn't you?", "\"Yes. I did. I know how it sounds, but I was checking about the bump.\""), .cross("The camera shows a white van scraping a car, doesn't it?", "\"Yes. It does. I did not know it was my van's bump.\""), .cross("You did not stop, did you?", "\"No. I did not stop. I thought it was the mirror.\""), .cross("The mirror had been loose for weeks, hadn't it?", "\"Yes. A mechanic confirmed it. I reported it, and it had not been fixed.\"")],
        openings: ("{V} waited in a drive-through lane on {DATE} when a delivery van cut the corner, scraped the driver's side of {V}'s car, and drove away. {V} photographed the van, a dispatch log shows {D} drove it, and {D} called the dispatcher and asked, Did anyone see that?", "The defense will present a loose mirror that had rattled for weeks, a bump that felt like a curb, and a driver who did not know. Not knowing is not leaving the scene on purpose."),
        closings: ("A white van scraping a car and leaving, a photo of the van, a dispatch log that names {D}, and a call asking whether anyone saw that. {D} did not stop.", "A mirror that had been loose for weeks and a bump that felt like a curb. The State has not proved that {D} knew a car had been hit."),
        timeline: [(0, "2:10 p.m.: the van enters the drive-through lane."), (0, "2:12 p.m.: the scrape."), (0, "2:30 p.m.: {V} reports the plate."), (1, "{DL} calls the deputy.")],
        identified: "A drive-through camera and dispatch records.",
        mood: .indifferent,
        genders: ["D": .male])

    static let coldCaseGenealogyV1 = SmallCases.make(
        key: "story.coldCaseGenealogy",
        category: .violent,
        headlines: ["Familial DNA Search Revives 1980s Convenience Store Killing", "Retired Sawmill Foreman Arrested in Decades-Old Murder"],
        law: "murder1",
        threshold: 7,
        spec: "With premeditation and deliberation, killed {V} at a roadside store in the 1980s.",
        ages: 68...76,
        victim: true,
        summary: "Nearly forty years ago, {V} was beaten to death while closing a roadside store at night. The case went cold. Last year, a lab retested fingernail scrapings with new methods and found a male profile. A familial search of a state database pointed to the family of {D}, a retired sawmill foreman who lived near the store then. {DL} says the old evidence sat unprotected for decades and that the familial match is not proof.",
        state: [E(.forensic, 3, "Fingernail DNA", "A male profile from scrapings consistent with {D}."), E(.document, 2, "Familial Search Report", "A relative's profile led investigators to {D}."), E(.document, 2, "Employment Records", "{D} worked at a sawmill two miles from the store."), E(.statement, 1, "Truck Sighting", "A 1980s witness reported a green pickup.")],
        defense: [E(.document, 2, "Evidence Storage", "The scrapings sat in a shed with no climate control for decades."), E(.document, 2, "Familial Error Rate", "Familial searches return many false leads."), E(.document, 1, "No Record", "No arrest record for {D} in forty years.")],
        role: "Forensic DNA scientist",
        exam: [.direct("What are your duties as a forensic DNA scientist?", "\"I analyze biological evidence and develop DNA profiles. I also review how old evidence was stored, because storage affects what the lab can and cannot say.\""), .direct("What case are you here about?", "\"Nearly forty years ago, {V} was beaten to death while closing a roadside store at night. The case went cold.\""), .direct("What did you do last year?", "\"My lab retested fingernail scrapings from {V} with new methods. We found a male profile in the scrapings.\""), .direct("How did the investigation reach {D}?", "\"A familial search of a state database pointed to the family of {D}. A relative's profile led investigators to {D.him}.\""), .direct("What do you know about the defendant?", "\"{D.He} is a retired sawmill foreman who lived near the store then. {D.He} worked at a sawmill two miles away.\""), .direct("What did a witness report?", "\"In the 1980s, a witness reported a green pickup near the store. That fits a truck {DL} may have driven.\""), .cross("Is the profile a match to the defendant?", "\"It is consistent with {D.him}. It came from a familial search, and I cannot say it is a direct match without a direct comparison.\""), .cross("How were the scrapings stored?", "\"In a shed with no climate control for decades. Heat and humidity can degrade DNA and raise contamination concerns.\""), .cross("How reliable is a familial search?", "\"It returns many false leads. A relative's profile may point toward a family, but not to one person.\""), .cross("Does the defendant have an arrest record?", "\"No. No record in forty years. I did not find any record linking {DL} to violence.\""), .cross("Could the profile belong to another relative?", "\"Yes. A second familial match later pointed to {D.his} sibling, who died in 1999 and drove a similar green pickup.\"")],
        defenseRole: "Retired evidence clerk",
        defenseExam: [.direct("How would you describe your job as a retired evidence clerk?", "\"I worked in an evidence room for many years. I handled items from cases like this, and I know how storage worked in the old days.\""), .direct("How was evidence stored in those days?", "\"In sheds and basements. There was no climate control. Items were often left on shelves for years with little oversight.\""), .direct("What happened to evidence from this case?", "\"The scrapings sat unprotected in a shed. I cannot say who handled them. The log is incomplete.\""), .direct("How could storage affect DNA?", "\"Heat and moisture can break down DNA. Handling can add contamination. Old evidence should be treated with caution.\""), .direct("Were chain of custody records reliable?", "\"Not always. Many records from that period are incomplete. I would not rely on them without question.\""), .direct("What would you tell the jury about old evidence?", "\"That it can be unreliable. Storage matters, and people should be careful about drawing strong conclusions.\""), .cross("Did you handle this evidence?", "\"No. I did not. I only know how evidence was stored in general.\""), .cross("Do you know the scrapings were contaminated?", "\"No. I cannot say that. I can only say the storage was poor.\""), .cross("Was the lab's retesting done properly?", "\"I do not know. I did not review the lab's work, and I am not a scientist.\""), .cross("Could the profile still be accurate?", "\"Yes. It could. I only say that the storage makes me uneasy.\""), .cross("Did you know {D}?", "\"No. I did not know {D}. I only know about the evidence from the records.\"")],
        theory: ("{D} killed a store clerk in the 1980s and left DNA under {V.his} fingernails.", "Old evidence and a familial lead that proves nothing."),
        allocution: "\"I have nothing more to say.\"",
        truths: ("{DL} sold the victim's ring at a pawnshop two weeks after the killing, a surviving ticket shows.", "A second familial match later pointed to {DL}'s brother, who died in 1999 and drove a similar green pickup."),
        defendant: [.direct("Describe your life near the store for the jury.", "\"I worked at the sawmill and lived near that store. I stopped there sometimes for supplies, as many people did.\""), .direct("Did you hurt {V}?", "\"No. I never did. I did not hurt anyone. I was shocked when deputies came after forty years.\""), .direct("Why did you sell {V}'s ring at a pawnshop?", "\"I bought a ring from someone I met and sold it later for money. I did not know it was {V}'s.\""), .direct("Do you know about the green pickup?", "\"I drove a pickup then, but many people did. My sibling drove a similar green pickup, and my sibling died in 1999.\""), .direct("What do you say about the DNA?", "\"The evidence sat in a shed for decades. I think it could be contaminated. I do not know how my relatives' profiles were matched.\""), .direct("How are you coping with what happened?", "\"Honestly, I feel crushed. I have lived a quiet life for forty years, and I did not do this.\""), .cross("You sold a ring two weeks after the killing, didn't you?", "\"Yes. I know a ticket shows it. I did not know whose ring it was.\""), .cross("You lived near the store then, didn't you?", "\"Yes. Many people did. I worked at a sawmill two miles from there.\""), .cross("You drove a pickup in the 1980s, didn't you?", "\"Yes. I did. So did many others. I do not remember its color clearly.\""), .cross("The profile is consistent with you, isn't it?", "\"That is what the scientist says. I do not know how, and I do not accept it.\""), .cross("You have no alibi from forty years ago, do you?", "\"No. How could anyone? I cannot remember that night, and neither can anyone else.\"")],
        openings: ("Nearly forty years ago, {V} was beaten to death while closing a roadside store at night, and the case went cold. Last year, a lab retested fingernail scrapings, found a male profile, and a familial search pointed to the family of {D}, a retired sawmill foreman who lived near the store then.", "The defense will present evidence that sat unprotected in a shed for decades, a familial match that returns many false leads, and a second match that pointed to a relative who died in 1999. A familial match is not proof."),
        closings: ("Fingernail DNA consistent with {D}, a familial search that led to {D}, a sawmill two miles away, a green pickup, and a ring sold two weeks after the killing. {V} deserves an answer.", "Evidence stored in a shed for decades, a familial search that returns false leads, and a second relative with a similar pickup who died in 1999. The State has not proved that {D} killed {V}."),
        timeline: [(-30, "The store is robbed twice in a month."), (0, "{V} is killed at closing."), (14000, "The scrapings are retested."), (14080, "A familial search points to {DL}'s family."), (14090, "A confirming sample matches; {DL} is arrested.")],
        identified: "A familial DNA search and a confirming sample.",
        mitigating: ["No prior criminal record"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof", "searchSeizure", "chainOfCustody"],
        genders: ["D": .male])

    static let barSkimmerPocketV1 = SmallCases.make(
        key: "story.barSkimmerPocket",
